"""
AI Code Generator Module
Handles intelligent code generation for multiple programming languages
"""

import os
from google import genai
from google.genai import types
from code_templates import get_template_code, list_available_templates

client = None

def get_client():
    """Get or initialize the Gemini client"""
    global client
    if client is None:
        api_key = os.environ.get("GEMINI_API_KEY")
        if not api_key:
            raise ValueError("GEMINI_API_KEY environment variable not set")
        client = genai.Client(api_key=api_key)
    return client

LANGUAGE_TEMPLATES = {
    "python": {
        "extension": ".py",
        "comment_style": "#",
        "editor": "notepad" if os.name == "nt" else "gedit"
    },
    "javascript": {
        "extension": ".js",
        "comment_style": "//",
        "editor": "notepad" if os.name == "nt" else "gedit"
    },
    "java": {
        "extension": ".java",
        "comment_style": "//",
        "editor": "notepad" if os.name == "nt" else "gedit"
    },
    "c": {
        "extension": ".c",
        "comment_style": "//",
        "editor": "notepad" if os.name == "nt" else "gedit"
    },
    "cpp": {
        "extension": ".cpp",
        "comment_style": "//",
        "editor": "notepad" if os.name == "nt" else "gedit"
    },
    "csharp": {
        "extension": ".cs",
        "comment_style": "//",
        "editor": "notepad" if os.name == "nt" else "gedit"
    },
    "ruby": {
        "extension": ".rb",
        "comment_style": "#",
        "editor": "notepad" if os.name == "nt" else "gedit"
    },
    "go": {
        "extension": ".go",
        "comment_style": "//",
        "editor": "notepad" if os.name == "nt" else "gedit"
    },
    "html": {
        "extension": ".html",
        "comment_style": "<!--",
        "editor": "notepad" if os.name == "nt" else "gedit"
    },
    "css": {
        "extension": ".css",
        "comment_style": "/*",
        "editor": "notepad" if os.name == "nt" else "gedit"
    }
}

def detect_language_from_description(description: str) -> str:
    """Detect programming language from description"""
    description_lower = description.lower()

    language_keywords = {
        "python": ["python", "py", "django", "flask"],
        "javascript": ["javascript", "js", "node", "react", "vue"],
        "java": ["java"],
        "c": ["c programming", " c code"],
        "cpp": ["c++", "cpp"],
        "csharp": ["c#", "csharp"],
        "ruby": ["ruby", "rails"],
        "go": ["go", "golang"],
        "html": ["html", "webpage"],
        "css": ["css", "styling"]
    }

    for lang, keywords in language_keywords.items():
        if any(keyword in description_lower for keyword in keywords):
            return lang

    return "python"

def clean_code_output(code: str) -> str:
    """Remove markdown code blocks and clean up the output"""
    code = code.strip()

    if code.startswith("```"):
        lines = code.split("\n")

        if lines[0].strip().startswith("```"):
            lines = lines[1:]

        if lines and lines[-1].strip() == "```":
            lines = lines[:-1]

        code = "\n".join(lines)

    return code.strip()

def generate_code(description: str, language: str | None = None) -> dict:
    """
    Generate code using templates (fast) or Gemini AI (fallback)

    Args:
        description: What the code should do
        language: Programming language (auto-detected if not provided)

    Returns:
        dict with code, language, and metadata
    """
    if not language:
        language = detect_language_from_description(description)

    language = language.lower()

    language_info = LANGUAGE_TEMPLATES.get(language, {
        "extension": ".txt",
        "comment_style": "#",
        "editor": "notepad"
    })

    # Try to get template code first (instant, reliable)
    template_code = get_template_code(description, language)
    if template_code:
        return {
            "success": True,
            "code": template_code,
            "language": language,
            "extension": language_info["extension"],
            "editor": language_info["editor"],
            "description": description,
            "source": "template"
        }

    # Fall back to AI generation if no template available
    prompt = f"""You are an expert {language} programmer. Generate clean, well-documented code for the following task:

TASK: {description}

REQUIREMENTS:
1. Write COMPLETE, WORKING {language} code
2. Include detailed comments explaining the logic
3. Follow {language} best practices and conventions
4. Make the code beginner-friendly and educational
5. Include example usage or test cases where appropriate
6. DO NOT include any explanations before or after the code
7. DO NOT use markdown formatting (no ```)
8. ONLY return the raw code

Generate the {language} code now:"""

    try:
        api_client = get_client()
        response = api_client.models.generate_content(
            model="gemini-2.0-flash",
            contents=prompt,
            config=types.GenerateContentConfig(
                temperature=0.7,
            )
        )

        if response.text:
            code = clean_code_output(response.text)

            return {
                "success": True,
                "code": code,
                "language": language,
                "extension": language_info["extension"],
                "editor": language_info["editor"],
                "description": description,
                "source": "ai"
            }
        else:
            return {
                "success": False,
                "error": "No code generated",
                "code": f"# Error: Could not generate code for: {description}"
            }

    except Exception as e:
        return {
            "success": False,
            "error": str(e),
            "code": f"# Error generating code: {str(e)}\n# Try one of these: {', '.join(list_available_templates())}"
        }

def generate_multiple_versions(description: str, language: str | None = None, count: int = 1) -> list:
    """Generate multiple versions of code for comparison"""
    versions = []

    for i in range(count):
        result = generate_code(description, language)
        if result["success"]:
            versions.append(result)

    return versions

def explain_code(code: str, language: str = "python") -> str:
    """Generate explanation for existing code"""
    prompt = f"""Explain the following {language} code in simple terms:

{code}

Provide a clear, beginner-friendly explanation of:
1. What the code does
2. How it works (step by step)
3. Key concepts used"""

    try:
        api_client = get_client()
        response = api_client.models.generate_content(
            model="gemini-2.0-flash",
            contents=prompt
        )
        return response.text or "Could not generate explanation"
    except Exception as e:
        return f"Error: {str(e)}"

def improve_code(code: str, language: str = "python") -> dict:
    """Suggest improvements for existing code"""
    prompt = f"""Analyze this {language} code and provide an improved version:

{code}

Improvements to make:
1. Better performance
2. More readable
3. Better error handling
4. Follow best practices
5. Add helpful comments

Return ONLY the improved code, no explanations."""

    try:
        api_client = get_client()
        response = api_client.models.generate_content(
            model="gemini-2.0-flash",
            contents=prompt
        )

        if response.text:
            improved_code = clean_code_output(response.text)
            return {
                "success": True,
                "code": improved_code,
                "language": language
            }
        else:
            return {
                "success": False,
                "error": "Could not improve code"
            }
    except Exception as e:
        return {
            "success": False,
            "error": str(e)
        }

def debug_code(code: str, error_message: str, language: str = "python") -> dict:
    """Debug code and fix errors"""
    prompt = f"""Fix the following {language} code that has this error:

ERROR: {error_message}

CODE:
{code}

Provide the corrected code with the bug fixed. Return ONLY the fixed code."""

    try:
        api_client = get_client()
        response = api_client.models.generate_content(
            model="gemini-2.0-flash",
            contents=prompt
        )

        if response.text:
            fixed_code = clean_code_output(response.text)
            return {
                "success": True,
                "code": fixed_code,
                "language": language
            }
        else:
            return {
                "success": False,
                "error": "Could not fix code"
            }
    except Exception as e:
        return {
            "success": False,
            "error": str(e)
        }

conversation_memory.py.content:
"""
Conversation Memory Module
Tracks conversation history and provides context awareness
"""

import json
import os
from datetime import datetime
from typing import List, Dict

class ConversationMemory:
    """Manages conversation history and context"""

    def __init__(self, max_history: int = 50):
        self.max_history = max_history
        self.history: List[Dict] = []
        self.context: Dict = {}
        self.load_history()

    def add_command(self, user_input: str, result: Dict, command_dict: Dict = None):
        """Add a command to history"""
        entry = {
            "timestamp": datetime.now().isoformat(),
            "user_input": user_input,
            "command": command_dict,
            "result": {
                "success": result.get("success"),
                "message": result.get("message", "")[:200]
            }
        }

        self.history.append(entry)

        if len(self.history) > self.max_history:
            self.history = self.history[-self.max_history:]

        self.update_context(entry)
        self.save_history()

    def update_context(self, entry: Dict):
        """Update context based on recent activity"""
        if entry["result"]["success"]:
            last_action = entry.get("command", {}).get("action", "")
            self.context["last_successful_action"] = last_action
            self.context["last_command"] = entry["user_input"]

            if "generated_code" in entry["result"]:
                self.context["last_generated_code"] = entry["result"]["generated_code"][:500]

    def get_recent_history(self, count: int = 10) -> List[Dict]:
        """Get recent command history"""
        return self.history[-count:] if self.history else []

    def get_context_summary(self) -> str:
        """Get a summary of current context"""
        if not self.history:
            return "No previous commands"

        recent = self.get_recent_history(5)
        summary = f"Recent commands ({len(recent)}):\n"

        for entry in recent:
            status = "✅" if entry["result"]["success"] else "❌"
            summary += f"  {status} {entry['user_input'][:50]}\n"

        return summary

    def search_history(self, query: str) -> List[Dict]:
        """Search command history"""
        query_lower = query.lower()
        results = []

        for entry in self.history:
            if query_lower in entry["user_input"].lower():
                results.append(entry)

        return results

    def get_last_code(self) -> str:
        """Get the last generated code"""
        return self.context.get("last_generated_code", "")

    def clear_history(self):
        """Clear all history"""
        self.history = []
        self.context = {}
        self.save_history()

    def save_history(self):
        """Save history to file"""
        try:
            with open("conversation_history.json", "w") as f:
                json.dump({
                    "history": self.history,
                    "context": self.context
                }, f, indent=2)
        except Exception:
            pass

    def load_history(self):
        """Load history from file"""
        try:
            if os.path.exists("conversation_history.json"):
                with open("conversation_history.json", "r") as f:
                    data = json.load(f)
                    self.history = data.get("history", [])[-self.max_history:]
                    self.context = data.get("context", {})
        except Exception:
            pass

    def get_statistics(self) -> Dict:
        """Get usage statistics"""
        total_commands = len(self.history)
        successful = sum(1 for e in self.history if e["result"]["success"])
        failed = total_commands - successful

        return {
            "total_commands": total_commands,
            "successful": successful,
            "failed": failed,
            "success_rate": f"{(successful/total_commands*100):.1f}%" if total_commands > 0 else "0%"
        }

code_executor.py.content:
"""
Code Execution Module
Safely execute generated code and show results
"""

import subprocess
import sys
import tempfile
import os
from typing import Dict

def execute_python_code(code: str, timeout: int = 10) -> Dict:
    """
    Execute Python code safely and return output

    Args:
        code: Python code to execute
        timeout: Maximum execution time in seconds

    Returns:
        Dict with success, output, and error
    """
    try:
        with tempfile.NamedTemporaryFile(mode='w', suffix='.py', delete=False) as f:
            f.write(code)
            temp_file = f.name

        try:
            result = subprocess.run(
                [sys.executable, temp_file],
                capture_output=True,
                text=True,
                timeout=timeout
            )

            return {
                "success": result.returncode == 0,
                "output": result.stdout,
                "error": result.stderr,
                "return_code": result.returncode
            }

        finally:
            if os.path.exists(temp_file):
                os.remove(temp_file)

    except subprocess.TimeoutExpired:
        return {
            "success": False,
            "output": "",
            "error": f"Execution timeout after {timeout} seconds",
            "return_code": -1
        }
    except Exception as e:
        return {
            "success": False,
            "output": "",
            "error": str(e),
            "return_code": -1
        }

def execute_javascript_code(code: str, timeout: int = 10) -> Dict:
    """Execute JavaScript code using Node.js"""
    try:
        with tempfile.NamedTemporaryFile(mode='w', suffix='.js', delete=False) as f:
            f.write(code)
            temp_file = f.name

        try:
            result = subprocess.run(
                ["node", temp_file],
                capture_output=True,
                text=True,
                timeout=timeout
            )

            return {
                "success": result.returncode == 0,
                "output": result.stdout,
                "error": result.stderr,
                "return_code": result.returncode
            }

        finally:
            if os.path.exists(temp_file):
                os.remove(temp_file)

    except FileNotFoundError:
        return {
            "success": False,
            "output": "",
            "error": "Node.js not installed",
            "return_code": -1
        }
    except subprocess.TimeoutExpired:
        return {
            "success": False,
            "output": "",
            "error": f"Execution timeout after {timeout} seconds",
            "return_code": -1
        }
    except Exception as e:
        return {
            "success": False,
            "output": "",
            "error": str(e),
            "return_code": -1
        }

def validate_code_safety(code: str, language: str = "python") -> Dict:
    """
    Check if code appears safe to execute

    Returns:
        Dict with is_safe flag and warnings
    """
    dangerous_patterns = {
        "python": [
            "import os", "import sys", "import subprocess",
            "exec(", "eval(", "__import__",
            "open(", "file(", "input(",
            "rmdir", "remove", "unlink"
        ],
        "javascript": [
            "require('fs')", "require('child_process')",
            "eval(", "exec(",
            "process.exit"
        ]
    }

    patterns = dangerous_patterns.get(language.lower(), [])
    warnings = []

    for pattern in patterns:
        if pattern in code:
            warnings.append(f"Potentially dangerous: {pattern}")

    return {
        "is_safe": len(warnings) == 0,
        "warnings": warnings,
        "recommendation": "Review before executing" if warnings else "Appears safe"
    }

