"""
Productivity Monitor Module
Screen time tracking, distraction blocking, activity logging, smart reminders
"""

import json
import os
import time
import psutil
from datetime import datetime, timedelta
import platform
import subprocess

class ProductivityMonitor:
    def __init__(self):
        # Use shared productivity_data directory
        from pathlib import Path
        self.data_dir = Path(__file__).parent.absolute() / "productivity_data"
        self.data_dir.mkdir(exist_ok=True)

        self.activity_log_file = self.data_dir / "activity_log.json"
        self.productivity_config_file = self.data_dir / "productivity_config.json"
        self.screen_time_file = self.data_dir / "screen_time.json"

        self.load_activity_log()
        self.load_config()
        self.load_screen_time()

        self.distraction_apps = ["chrome", "firefox", "youtube", "facebook", "twitter", "instagram", "reddit", "tiktok"]
        self.productive_apps = ["vscode", "pycharm", "word", "excel", "notion", "sublime"]

    def load_activity_log(self):
        """Load activity log"""
        if os.path.exists(self.activity_log_file):
            with open(self.activity_log_file, 'r') as f:
                self.activity_log = json.load(f)
        else:
            self.activity_log = []

    def save_activity_log(self):
        """Save activity log"""
        with open(self.activity_log_file, 'w') as f:
            json.dump(self.activity_log, f, indent=2)

    def load_config(self):
        """Load productivity configuration"""
        if os.path.exists(self.productivity_config_file):
            with open(self.productivity_config_file, 'r') as f:
                self.config = json.load(f)
        else:
            self.config = {
                "block_distractions_enabled": False,
                "block_after_hours": "22:00",
                "reminders": {
                    "water": {"enabled": True, "interval_minutes": 30},
                    "break": {"enabled": True, "interval_minutes": 60},
                    "posture": {"enabled": True, "interval_minutes": 45}
                }
            }
            self.save_config()

    def save_config(self):
        """Save productivity configuration"""
        with open(self.productivity_config_file, 'w') as f:
            json.dump(self.config, f, indent=2)

    def load_screen_time(self):
        """Load screen time data"""
        if os.path.exists(self.screen_time_file):
            with open(self.screen_time_file, 'r') as f:
                self.screen_time = json.load(f)
        else:
            self.screen_time = {}

    def save_screen_time(self):
        """Save screen time data"""
        with open(self.screen_time_file, 'w') as f:
            json.dump(self.screen_time, f, indent=2)

    def log_activity(self, activity_type, description):
        """Log an activity"""
        entry = {
            "timestamp": datetime.now().isoformat(),
            "type": activity_type,
            "description": description
        }

        self.activity_log.append(entry)

        if len(self.activity_log) > 1000:
            self.activity_log = self.activity_log[-1000:]

        self.save_activity_log()
        return f"✅ Activity logged: {description}"

    def get_active_window(self):
        """Get currently active window/app"""
        try:
            if platform.system() == "Windows":
                try:
                    import win32gui
                    window = win32gui.GetForegroundWindow()
                    return win32gui.GetWindowText(window)
                except ImportError:
                    return "Windows (win32gui not available)"
            elif platform.system() == "Darwin":
                script = 'tell application "System Events" to get name of first application process whose frontmost is true'
                return subprocess.check_output(['osascript', '-e', script]).decode('utf-8').strip()
            elif platform.system() == "Linux":
                return subprocess.check_output(['xdotool', 'getactivewindow', 'getwindowname']).decode('utf-8').strip()
        except:
            return "Unknown"

    def track_screen_time(self, duration_minutes=60):
        """Track screen time for running apps"""
        print(f"⏱️ Tracking screen time for {duration_minutes} minutes...")

        today = datetime.now().strftime("%Y-%m-%d")
        if today not in self.screen_time:
            self.screen_time[today] = {}

        start_time = time.time()
        check_interval = 5

        while time.time() - start_time < duration_minutes * 60:
            active_window = self.get_active_window()

            if active_window != "Unknown":
                if active_window not in self.screen_time[today]:
                    self.screen_time[today][active_window] = 0

                self.screen_time[today][active_window] += check_interval

            time.sleep(check_interval)

        self.save_screen_time()
        return f"✅ Screen time tracking complete for {duration_minutes} minutes"

    def get_screen_time_dashboard(self, days=7):
        """Generate screen time dashboard"""
        try:
            result = f"📊 Screen Time Dashboard (Last {days} days):\n\n"

            dates = sorted(self.screen_time.keys(), reverse=True)[:days]

            for date in dates:
                day_data = self.screen_time[date]
                total_seconds = sum(day_data.values())
                total_hours = total_seconds / 3600

                result += f"📅 {date} - {total_hours:.1f} hours total\n"

                sorted_apps = sorted(day_data.items(), key=lambda x: x[1], reverse=True)[:5]

                for app, seconds in sorted_apps:
                    hours = seconds / 3600
                    result += f"  • {app}: {hours:.1f}h\n"

                result += "\n"

            if not dates:
                return "ℹ️ No screen time data available"

            return result
        except Exception as e:
            return f"❌ Failed to generate dashboard: {str(e)}"

    def block_distractions(self):
        """Block distraction apps"""
        try:
            blocked = []

            for proc in psutil.process_iter(['name']):
                try:
                    proc_name = proc.info['name'].lower()

                    for distraction in self.distraction_apps:
                        if distraction in proc_name:
                            proc.terminate()
                            blocked.append(proc.info['name'])
                            break
                except:
                    continue

            if blocked:
                return f"✅ Blocked {len(blocked)} distraction(s): {', '.join(set(blocked))}"
            else:
                return "✅ No distractions running"
        except Exception as e:
            return f"❌ Failed to block distractions: {str(e)}"

    def enable_focus_mode(self, hours=2):
        """Enable focus mode - block distractions for specified hours"""
        self.config["block_distractions_enabled"] = True
        self.config["focus_until"] = (datetime.now() + timedelta(hours=hours)).isoformat()
        self.save_config()

        self.block_distractions()

        return f"🎯 Focus mode enabled for {hours} hours. Distractions blocked!"

    def disable_focus_mode(self):
        """Disable focus mode"""
        self.config["block_distractions_enabled"] = False
        self.save_config()
        return "✅ Focus mode disabled"

    def get_productivity_score(self):
        """Calculate productivity score for today"""
        try:
            today = datetime.now().strftime("%Y-%m-%d")

            if today not in self.screen_time:
                return "ℹ️ No data for today"

            day_data = self.screen_time[today]

            productive_time = 0
            distraction_time = 0

            for app, seconds in day_data.items():
                app_lower = app.lower()

                is_productive = any(prod in app_lower for prod in self.productive_apps)
                is_distraction = any(dist in app_lower for dist in self.distraction_apps)

                if is_productive:
                    productive_time += seconds
                elif is_distraction:
                    distraction_time += seconds

            total_time = productive_time + distraction_time

            if total_time == 0:
                return "ℹ️ Not enough data for today"

            score = (productive_time / total_time) * 100

            result = f"📈 Productivity Score for Today: {score:.1f}%\n\n"
            result += f"✅ Productive time: {productive_time/3600:.1f} hours\n"
            result += f"⚠️ Distraction time: {distraction_time/3600:.1f} hours\n"

            if score >= 70:
                result += "\n🏆 Excellent! Keep up the great work!"
            elif score >= 50:
                result += "\n👍 Good job! Room for improvement."
            else:
                result += "\n💡 Try to minimize distractions."

            return result
        except Exception as e:
            return f"❌ Failed to calculate score: {str(e)}"

    def send_reminder(self, reminder_type):
        """Send a reminder notification"""
        reminders = {
            "water": "💧 Time to drink water! Stay hydrated.",
            "break": "☕ Take a 5-minute break. Rest your eyes!",
            "posture": "🪑 Check your posture. Sit up straight!",
            "stretch": "🤸 Time to stretch! Move your body.",
            "eyes": "👀 Look away from the screen for 20 seconds."
        }

        message = reminders.get(reminder_type, "⏰ Reminder!")

        try:
            if platform.system() == "Windows":
                try:
                    from win10toast import ToastNotifier
                    toaster = ToastNotifier()
                    toaster.show_toast("Productivity Reminder", message, duration=10)
                except ImportError:
                    print(f"⏰ {message}")
            elif platform.system() == "Darwin":
                subprocess.run(['osascript', '-e', f'display notification "{message}" with title "Productivity Reminder"'])
            elif platform.system() == "Linux":
                subprocess.run(['notify-send', "Productivity Reminder", message])

            return f"✅ {message}"
        except:
            return f"ℹ️ {message}"

    def generate_daily_summary(self):
        """Generate daily activity summary"""
        try:
            today = datetime.now().strftime("%Y-%m-%d")

            today_activities = [a for a in self.activity_log if a['timestamp'].startswith(today)]

            result = f"📋 Daily Summary for {today}:\n\n"
            result += f"Total activities logged: {len(today_activities)}\n\n"

            if today_activities:
                result += "Recent activities:\n"
                for activity in today_activities[-10:]:
                    time = datetime.fromisoformat(activity['timestamp']).strftime("%H:%M")
                    result += f"  [{time}] {activity['description']}\n"

            result += "\n" + self.get_productivity_score()

            return result
        except Exception as e:
            return f"❌ Failed to generate summary: {str(e)}"

if __name__ == "__main__":
    monitor = ProductivityMonitor()
    print("Productivity Monitor Module - Testing")
    print(monitor.get_screen_time_dashboard())

file_manager.py.content:
"""
Advanced File Manager Module
Auto-rename, compress old files, auto-backup, advanced file operations
"""

import os
import shutil
import hashlib
import gzip
import json
from datetime import datetime, timedelta
from pathlib import Path
import re

class FileManager:
    def __init__(self):
        self.backup_config_file = "backup_config.json"
        self.load_backup_config()

    def load_backup_config(self):
        """Load backup configuration"""
        if os.path.exists(self.backup_config_file):
            with open(self.backup_config_file, 'r') as f:
                self.backup_config = json.load(f)
        else:
            self.backup_config = {
                "enabled": False,
                "folders": [],
                "backup_location": str(Path.home() / "Backups"),
                "schedule": "daily"
            }
            self.save_backup_config()

    def save_backup_config(self):
        """Save backup configuration"""
        with open(self.backup_config_file, 'w') as f:
            json.dump(self.backup_config, f, indent=2)

    def auto_rename_files(self, folder_path, pattern="clean"):
        """Auto-rename messy files"""
        try:
            renamed = []

            for filename in os.listdir(folder_path):
                file_path = os.path.join(folder_path, filename)

                if os.path.isfile(file_path):
                    new_name = filename

                    if pattern == "clean":
                        new_name = re.sub(r'\s*\(\d+\)\s*', '', new_name)
                        new_name = re.sub(r'\s+', '_', new_name)
                        new_name = new_name.lower()

                    elif pattern == "timestamp":
                        name, ext = os.path.splitext(filename)
                        timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
                        new_name = f"{name}_{timestamp}{ext}"

                    elif pattern == "numbered":
                        name, ext = os.path.splitext(filename)
                        counter = 1
                        new_name = f"{counter:03d}_{name}{ext}"

                    if new_name != filename:
                        new_path = os.path.join(folder_path, new_name)

                        if not os.path.exists(new_path):
                            os.rename(file_path, new_path)
                            renamed.append(f"{filename} → {new_name}")

            if renamed:
                result = f"✅ Renamed {len(renamed)} files:\n"
                for item in renamed[:10]:
                    result += f"  • {item}\n"
                if len(renamed) > 10:
                    result += f"  ... and {len(renamed) - 10} more"
                return result
            else:
                return "ℹ️ No files to rename"
        except Exception as e:
            return f"❌ Failed to rename files: {str(e)}"

    def find_duplicates(self, folder_path):
        """Find duplicate files by hash"""
        try:
            hashes = {}
            duplicates = []

            for root, dirs, files in os.walk(folder_path):
                for filename in files:
                    file_path = os.path.join(root, filename)

                    try:
                        file_hash = self.get_file_hash(file_path)

                        if file_hash in hashes:
                            duplicates.append({
                                "original": hashes[file_hash],
                                "duplicate": file_path,
                                "size": os.path.getsize(file_path)
                            })
                        else:
                            hashes[file_hash] = file_path
                    except:
                        continue

            if duplicates:
                total_wasted = sum(d['size'] for d in duplicates)
                result = f"🔍 Found {len(duplicates)} duplicate files (wasting {total_wasted/(1024*1024):.2f} MB):\n"

                for dup in duplicates[:10]:
                    result += f"  • {os.path.basename(dup['duplicate'])} ({dup['size']/(1024*1024):.2f} MB)\n"
                    result += f"    Original: {dup['original']}\n"

                if len(duplicates) > 10:
                    result += f"  ... and {len(duplicates) - 10} more"

                return result
            else:
                return "✅ No duplicate files found"
        except Exception as e:
            return f"❌ Failed to find duplicates: {str(e)}"

    def get_file_hash(self, file_path):
        """Calculate MD5 hash of a file"""
        hasher = hashlib.md5()
        with open(file_path, 'rb') as f:
            for chunk in iter(lambda: f.read(4096), b""):
                hasher.update(chunk)
        return hasher.hexdigest()

    def compress_old_files(self, folder_path, days_old=90):
        """Compress files older than specified days"""
        try:
            cutoff_date = datetime.now() - timedelta(days=days_old)
            compressed = []

            for root, dirs, files in os.walk(folder_path):
                for filename in files:
                    if filename.endswith('.gz'):
                        continue

                    file_path = os.path.join(root, filename)

                    try:
                        mtime = datetime.fromtimestamp(os.path.getmtime(file_path))

                        if mtime < cutoff_date:
                            original_size = os.path.getsize(file_path)

                            with open(file_path, 'rb') as f_in:
                                with gzip.open(f"{file_path}.gz", 'wb') as f_out:
                                    shutil.copyfileobj(f_in, f_out)

                            compressed_size = os.path.getsize(f"{file_path}.gz")
                            os.remove(file_path)

                            saved = original_size - compressed_size
                            compressed.append(f"{filename} (saved {saved/(1024*1024):.2f} MB)")
                    except:
                        continue

            if compressed:
                result = f"✅ Compressed {len(compressed)} old files:\n"
                for item in compressed[:10]:
                    result += f"  • {item}\n"
                if len(compressed) > 10:
                    result += f"  ... and {len(compressed) - 10} more"
                return result
            else:
                return f"ℹ️ No files older than {days_old} days found"
        except Exception as e:
            return f"❌ Failed to compress files: {str(e)}"

    def backup_folder(self, source_folder, destination=None):
        """Backup a folder to destination"""
        try:
            if destination is None:
                destination = self.backup_config["backup_location"]

            os.makedirs(destination, exist_ok=True)

            timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
            backup_name = f"{os.path.basename(source_folder)}_backup_{timestamp}"
            backup_path = os.path.join(destination, backup_name)

            shutil.copytree(source_folder, backup_path)

            total_size = sum(
                os.path.getsize(os.path.join(dirpath, filename))
                for dirpath, _, filenames in os.walk(backup_path)
                for filename in filenames
            )

            return f"✅ Backup created: {backup_path} ({total_size/(1024*1024):.2f} MB)"
        except Exception as e:
            return f"❌ Backup failed: {str(e)}"

    def add_backup_folder(self, folder_path):
        """Add folder to auto-backup list"""
        if folder_path not in self.backup_config["folders"]:
            self.backup_config["folders"].append(folder_path)
            self.save_backup_config()
            return f"✅ Added to backup list: {folder_path}"
        return f"ℹ️ Already in backup list: {folder_path}"

    def enable_auto_backup(self):
        """Enable automatic backups"""
        self.backup_config["enabled"] = True
        self.save_backup_config()
        return "✅ Auto-backup enabled"

    def run_backups(self):
        """Run backups for all configured folders"""
        if not self.backup_config["enabled"]:
            return "ℹ️ Auto-backup is disabled"

        results = []
        for folder in self.backup_config["folders"]:
            if os.path.exists(folder):
                result = self.backup_folder(folder)
                results.append(result)

        return "\n".join(results) if results else "ℹ️ No folders to backup"

    def list_backups(self):
        """List all available backups"""
        try:
            backup_location = self.backup_config["backup_location"]

            if not os.path.exists(backup_location):
                return "ℹ️ No backups found"

            backups = []
            for item in os.listdir(backup_location):
                item_path = os.path.join(backup_location, item)
                if os.path.isdir(item_path):
                    size = sum(
                        os.path.getsize(os.path.join(dirpath, filename))
                        for dirpath, _, filenames in os.walk(item_path)
                        for filename in filenames
                    )
                    mtime = datetime.fromtimestamp(os.path.getmtime(item_path))
                    backups.append({
                        "name": item,
                        "size_mb": round(size / (1024 * 1024), 2),
                        "date": mtime.strftime("%Y-%m-%d %H:%M")
                    })

            if backups:
                result = "💾 Available Backups:\n"
                for backup in sorted(backups, key=lambda x: x['date'], reverse=True):
                    result += f"  • {backup['name']} - {backup['size_mb']} MB ({backup['date']})\n"
                return result
            else:
                return "ℹ️ No backups found"
        except Exception as e:
            return f"❌ Failed to list backups: {str(e)}"

if __name__ == "__main__":
    manager = FileManager()
    print("File Manager Module - Testing")
    print(manager.list_backups())

download_organizer.py.content:
"""
Download Organizer Module
Auto-organize downloads into categorized folders
"""

import os
import shutil
from pathlib import Path
import time
from watchdog.observers import Observer
from watchdog.events import FileSystemEventHandler
import json

class DownloadOrganizer:
    def __init__(self, download_path=None):
        if download_path is None:
            self.download_path = str(Path.home() / "Downloads")
        else:
            self.download_path = download_path

        self.categories = {
            "Images": [".jpg", ".jpeg", ".png", ".gif", ".bmp", ".svg", ".ico", ".webp"],
            "Documents": [".pdf", ".doc", ".docx", ".txt", ".rtf", ".odt", ".xls", ".xlsx", ".ppt", ".pptx"],
            "Videos": [".mp4", ".avi", ".mkv", ".mov", ".wmv", ".flv", ".webm"],
            "Audio": [".mp3", ".wav", ".flac", ".aac", ".ogg", ".m4a", ".wma"],
            "Archives": [".zip", ".rar", ".7z", ".tar", ".gz", ".bz2"],
            "Installers": [".exe", ".msi", ".dmg", ".pkg", ".deb", ".rpm", ".apk"],
            "Code": [".py", ".js", ".java", ".cpp", ".c", ".html", ".css", ".php", ".rb", ".go"],
            "Data": [".json", ".xml", ".csv", ".sql", ".db", ".sqlite"]
        }

        self.config_file = "organizer_config.json"
        self.load_config()

    def load_config(self):
        """Load organizer configuration"""
        if os.path.exists(self.config_file):
            with open(self.config_file, 'r') as f:
                config = json.load(f)
                self.auto_organize_enabled = config.get("auto_organize", False)
        else:
            self.auto_organize_enabled = False
            self.save_config()

    def save_config(self):
        """Save organizer configuration"""
        with open(self.config_file, 'w') as f:
            json.dump({"auto_organize": self.auto_organize_enabled}, f, indent=2)

    def get_category(self, filename):
        """Determine category for a file"""
        ext = os.path.splitext(filename)[1].lower()

        for category, extensions in self.categories.items():
            if ext in extensions:
                return category

        return "Others"

    def organize_downloads(self):
        """Organize all files in downloads folder"""
        try:
            if not os.path.exists(self.download_path):
                return f"❌ Download folder not found: {self.download_path}"

            organized = []

            for filename in os.listdir(self.download_path):
                file_path = os.path.join(self.download_path, filename)

                if os.path.isfile(file_path):
                    category = self.get_category(filename)
                    category_folder = os.path.join(self.download_path, category)

                    os.makedirs(category_folder, exist_ok=True)

                    dest_path = os.path.join(category_folder, filename)

                    if os.path.exists(dest_path):
                        base, ext = os.path.splitext(filename)
                        counter = 1
                        while os.path.exists(dest_path):
                            dest_path = os.path.join(category_folder, f"{base}_{counter}{ext}")
                            counter += 1

                    shutil.move(file_path, dest_path)
                    organized.append(f"{filename} → {category}")

            if organized:
                result = f"✅ Organized {len(organized)} files:\n"
                for item in organized[:10]:
                    result += f"  • {item}\n"
                if len(organized) > 10:
                    result += f"  ... and {len(organized) - 10} more"
                return result
            else:
                return "ℹ️ No files to organize"
        except Exception as e:
            return f"❌ Failed to organize downloads: {str(e)}"

    def enable_auto_organize(self):
        """Enable automatic organization of downloads"""
        self.auto_organize_enabled = True
        self.save_config()
        return "✅ Auto-organize enabled. New downloads will be organized automatically."

    def disable_auto_organize(self):
        """Disable automatic organization"""
        self.auto_organize_enabled = False
        self.save_config()
        return "✅ Auto-organize disabled"

    def add_custom_category(self, category_name, extensions):
        """Add a custom file category"""
        self.categories[category_name] = extensions
        return f"✅ Added category '{category_name}' with {len(extensions)} extensions"

    def get_download_stats(self):
        """Get statistics about downloads folder"""
        try:
            stats = {}
            total_size = 0
            total_files = 0

            for category in self.categories.keys():
                category_path = os.path.join(self.download_path, category)
                if os.path.exists(category_path):
                    files = [f for f in os.listdir(category_path) if os.path.isfile(os.path.join(category_path, f))]
                    size = sum(os.path.getsize(os.path.join(category_path, f)) for f in files)
                    stats[category] = {"files": len(files), "size_mb": round(size / (1024 * 1024), 2)}
                    total_size += size
                    total_files += len(files)

            result = "📊 Downloads Statistics:\n"
            result += f"Total: {total_files} files, {round(total_size / (1024 * 1024), 2)} MB\n\n"

            for category, data in sorted(stats.items(), key=lambda x: x[1]['size_mb'], reverse=True):
                result += f"  {category}: {data['files']} files, {data['size_mb']} MB\n"

            return result
        except Exception as e:
            return f"❌ Failed to get stats: {str(e)}"

class DownloadWatcher(FileSystemEventHandler):
    """Watch for new downloads and organize them"""

    def __init__(self, organizer):
        self.organizer = organizer

    def on_created(self, event):
        """Handle new file creation"""
        if not event.is_directory and self.organizer.auto_organize_enabled:
            time.sleep(1)
            filename = os.path.basename(event.src_path)
            category = self.organizer.get_category(filename)
            category_folder = os.path.join(self.organizer.download_path, category)

            os.makedirs(category_folder, exist_ok=True)

            dest_path = os.path.join(category_folder, filename)
            try:
                shutil.move(event.src_path, dest_path)
                print(f"✅ Auto-organized: {filename} → {category}")
            except:
                pass

def start_auto_organizer():
    """Start the automatic download organizer"""
    organizer = DownloadOrganizer()
    event_handler = DownloadWatcher(organizer)
    observer = Observer()
    observer.schedule(event_handler, organizer.download_path, recursive=False)
    observer.start()

    print(f"✅ Auto-organizer started for: {organizer.download_path}")

    try:
        while True:
            time.sleep(10)
    except KeyboardInterrupt:
        observer.stop()
    observer.join()

if __name__ == "__main__":
    organizer = DownloadOrganizer()
    print("Download Organizer Module - Testing")
    print(organizer.get_download_stats())

web_automation.py.content:
"""
Web Automation Module
Auto-login, web scraping shortcuts, clipboard history with AI search
"""

import json
import os
from datetime import datetime
import pyperclip
import time
import webbrowser
from cryptography.fernet import Fernet
import base64

class WebAutomation:
    def __init__(self):
        self.credentials_file = "credentials.enc"
        self.clipboard_history_file = "clipboard_history.json"
        self.scrapers_file = "web_scrapers.json"
        self.clipboard_history = []
        self.max_clipboard_items = 100

        self.encryption_key = self.get_or_create_key()
        self.load_clipboard_history()
        self.load_scrapers()

    def get_or_create_key(self):
        """Get or create encryption key for credentials"""
        key_file = ".encryption_key"
        if os.path.exists(key_file):
            with open(key_file, 'rb') as f:
                return f.read()
        else:
            key = Fernet.generate_key()
            with open(key_file, 'wb') as f:
                f.write(key)
            return key

    def load_clipboard_history(self):
        """Load clipboard history"""
        if os.path.exists(self.clipboard_history_file):
            with open(self.clipboard_history_file, 'r') as f:
                self.clipboard_history = json.load(f)
        else:
            self.clipboard_history = []

    def save_clipboard_history(self):
        """Save clipboard history"""
        with open(self.clipboard_history_file, 'w') as f:
            json.dump(self.clipboard_history, f, indent=2)

    def load_scrapers(self):
        """Load web scraper configurations"""
        if os.path.exists(self.scrapers_file):
            with open(self.scrapers_file, 'r') as f:
                self.scrapers = json.load(f)
        else:
            self.scrapers = {
                "weather": {
                    "url": "https://wttr.in/?format=3",
                    "description": "Get current weather"
                },
                "crypto": {
                    "url": "https://api.coindesk.com/v1/bpi/currentprice.json",
                    "description": "Get Bitcoin price"
                }
            }
            self.save_scrapers()

    def save_scrapers(self):
        """Save web scraper configurations"""
        with open(self.scrapers_file, 'w') as f:
            json.dump(self.scrapers, f, indent=2)

    def save_credentials(self, site_name, username, password):
        """Safely save login credentials (encrypted)"""
        try:
            fernet = Fernet(self.encryption_key)

            credentials = {}
            if os.path.exists(self.credentials_file):
                with open(self.credentials_file, 'rb') as f:
                    encrypted_data = f.read()
                    if encrypted_data:
                        decrypted_data = fernet.decrypt(encrypted_data)
                        credentials = json.loads(decrypted_data)

            credentials[site_name] = {
                "username": username,
                "password": password,
                "saved_at": datetime.now().isoformat()
            }

            encrypted_data = fernet.encrypt(json.dumps(credentials).encode())

            with open(self.credentials_file, 'wb') as f:
                f.write(encrypted_data)

            return f"✅ Credentials saved for {site_name}"
        except Exception as e:
            return f"❌ Failed to save credentials: {str(e)}"

    def get_credentials(self, site_name):
        """Retrieve saved credentials"""
        try:
            if not os.path.exists(self.credentials_file):
                return None

            fernet = Fernet(self.encryption_key)

            with open(self.credentials_file, 'rb') as f:
                encrypted_data = f.read()
                decrypted_data = fernet.decrypt(encrypted_data)
                credentials = json.loads(decrypted_data)

            return credentials.get(site_name)
        except Exception as e:
            return None

    def list_saved_sites(self):
        """List all sites with saved credentials"""
        try:
            if not os.path.exists(self.credentials_file):
                return "ℹ️ No saved credentials"

            fernet = Fernet(self.encryption_key)

            with open(self.credentials_file, 'rb') as f:
                encrypted_data = f.read()
                decrypted_data = fernet.decrypt(encrypted_data)
                credentials = json.loads(decrypted_data)

            result = "🔐 Saved Login Sites:\n"
            for site, data in credentials.items():
                saved_date = datetime.fromisoformat(data['saved_at']).strftime("%Y-%m-%d")
                result += f"  • {site} (saved {saved_date})\n"

            return result
        except Exception as e:
            return f"❌ Failed to list sites: {str(e)}"

    def add_to_clipboard_history(self, text):
        """Add text to clipboard history"""
        if text and text.strip():
            item = {
                "text": text[:500],
                "timestamp": datetime.now().isoformat(),
                "length": len(text)
            }

            self.clipboard_history.insert(0, item)

            self.clipboard_history = self.clipboard_history[:self.max_clipboard_items]

            self.save_clipboard_history()

    def get_clipboard_history(self, limit=10):
        """Get recent clipboard history"""
        if not self.clipboard_history:
            return "ℹ️ Clipboard history is empty"

        result = f"📋 Clipboard History (last {min(limit, len(self.clipboard_history))} items):\n\n"

        for i, item in enumerate(self.clipboard_history[:limit], 1):
            timestamp = datetime.fromisoformat(item['timestamp']).strftime("%H:%M:%S")
            preview = item['text'][:60] + "..." if len(item['text']) > 60 else item['text']
            result += f"{i}. [{timestamp}] {preview}\n"

        return result

    def search_clipboard_history(self, query):
        """Search clipboard history"""
        results = []

        for item in self.clipboard_history:
            if query.lower() in item['text'].lower():
                results.append(item)

        if not results:
            return f"ℹ️ No results found for '{query}'"

        result = f"🔍 Found {len(results)} results for '{query}':\n\n"

        for i, item in enumerate(results[:10], 1):
            timestamp = datetime.fromisoformat(item['timestamp']).strftime("%Y-%m-%d %H:%M")
            preview = item['text'][:80] + "..." if len(item['text']) > 80 else item['text']
            result += f"{i}. [{timestamp}] {preview}\n"

        return result

    def restore_from_clipboard_history(self, index):
        """Restore item from clipboard history"""
        try:
            if 0 <= index < len(self.clipboard_history):
                text = self.clipboard_history[index]['text']
                pyperclip.copy(text)
                return f"✅ Restored to clipboard: {text[:50]}..."
            else:
                return f"❌ Invalid index: {index}"
        except Exception as e:
            return f"❌ Failed to restore: {str(e)}"

    def add_scraper(self, name, url, description=""):
        """Add a web scraper shortcut"""
        self.scrapers[name] = {
            "url": url,
            "description": description
        }
        self.save_scrapers()
        return f"✅ Scraper '{name}' added"

    def run_scraper(self, name):
        """Run a saved web scraper"""
        if name not in self.scrapers:
            return f"❌ Scraper '{name}' not found"

        scraper = self.scrapers[name]
        webbrowser.open(scraper['url'])
        return f"✅ Opened: {scraper['description'] or name}"

    def list_scrapers(self):
        """List all saved scrapers"""
        if not self.scrapers:
            return "ℹ️ No scrapers configured"

        result = "🕷️ Web Scrapers:\n"
        for name, data in self.scrapers.items():
            result += f"  • {name}: {data['description']}\n"

        return result

    def quick_search(self, query, engine="google"):
        """Quick web search"""
        engines = {
            "google": f"https://www.google.com/search?q={query}",
            "bing": f"https://www.bing.com/search?q={query}",
            "duckduckgo": f"https://duckduckgo.com/?q={query}",
            "youtube": f"https://www.youtube.com/results?search_query={query}",
            "github": f"https://github.com/search?q={query}"
        }

        url = engines.get(engine, engines["google"])
        webbrowser.open(url)
        return f"✅ Searching {engine} for: {query}"

    def monitor_clipboard(self, duration_seconds=60):
        """Monitor clipboard for changes and save to history"""
        print(f"📋 Monitoring clipboard for {duration_seconds} seconds...")

        last_text = ""
        start_time = time.time()

        while time.time() - start_time < duration_seconds:
            try:
                current_text = pyperclip.paste()

                if current_text != last_text and current_text.strip():
                    self.add_to_clipboard_history(current_text)
                    print(f"✅ Saved: {current_text[:50]}...")
                    last_text = current_text

                time.sleep(1)
            except:
                continue

        return f"✅ Clipboard monitoring complete. Saved {len(self.clipboard_history)} items."

if __name__ == "__main__":
