        context['last_accessed'] = datetime.now().isoformat()

        self.current_context = context
        self.save_contexts()

        return {
            "success": True,
            "context": context_name,
            "project_path": context['project_path'],
            "open_files": context['open_files'],
            "notes": context.get('notes', '')
        }

