"""
🛡️ Activity Monitoring System
Detect suspicious behavior and security anomalies in real-time
"""

import os
import json
import psutil
import hashlib
from datetime import datetime, timedelta
from typing import Dict, List, Any, Optional
from collections import deque, Counter
import threading
import time

class ActivityMonitoringSystem:
    """
    Advanced activity monitoring and threat detection system
    Features:
    - Real-time process monitoring
    - Failed authentication tracking
    - Unusual activity detection
    - Resource usage monitoring
    - Automated threat response
    """

    def __init__(self):
        self.data_dir = "activity_monitoring"
        self.activity_log_file = os.path.join(self.data_dir, "activity_log.json")
        self.threat_log_file = os.path.join(self.data_dir, "threat_log.json")
        self.config_file = os.path.join(self.data_dir, "monitoring_config.json")

        os.makedirs(self.data_dir, exist_ok=True)

        self.config = self._load_config()
        self.activity_log = self._load_activity_log()
        self.threat_log = self._load_threat_log()

        self.recent_activities = deque(maxlen=1000)
        self.failed_auth_attempts = deque(maxlen=100)

        self.monitoring_active = False
        self.monitor_thread = None

        self.threat_patterns = {
            "multiple_failed_logins": {
                "threshold": 3,
                "time_window_minutes": 5,
                "severity": "high"
            },
            "unusual_process": {
                "suspicious_names": ["hack", "crack", "keygen", "malware"],
                "severity": "critical"
            },
            "high_cpu_usage": {
                "threshold": 90,
                "duration_seconds": 300,
                "severity": "medium"
            },
            "high_memory_usage": {
                "threshold": 90,
                "duration_seconds": 300,
                "severity": "medium"
            },
            "rapid_file_access": {
                "threshold": 100,
                "time_window_seconds": 60,
                "severity": "medium"
            },
            "privilege_escalation": {
                "severity": "critical"
            }
        }

    def _load_config(self) -> Dict:
        """Load monitoring configuration"""
        if os.path.exists(self.config_file):
            try:
                with open(self.config_file, 'r') as f:
                    return json.load(f)
            except:
                pass

        return {
            "monitoring_enabled": False,
            "auto_response_enabled": False,
            "alert_on_threats": True,
            "log_all_activities": True,
            "process_monitoring": True,
            "network_monitoring": False,
            "file_integrity_monitoring": False,
            "alert_email": None,
            "blocked_processes": [],
            "whitelisted_processes": []
        }

    def _save_config(self):
        """Save monitoring configuration"""
        try:
            with open(self.config_file, 'w') as f:
                json.dump(self.config, f, indent=2)
        except Exception as e:
            print(f"Error saving config: {e}")

    def _load_activity_log(self) -> List:
        """Load activity log"""
        if os.path.exists(self.activity_log_file):
            try:
                with open(self.activity_log_file, 'r') as f:
                    return json.load(f)
            except:
                pass
        return []

    def _save_activity_log(self):
        """Save activity log"""
        try:
            with open(self.activity_log_file, 'w') as f:
                json.dump(self.activity_log[-1000:], f, indent=2)
        except Exception as e:
            print(f"Error saving activity log: {e}")

    def _load_threat_log(self) -> List:
        """Load threat log"""
        if os.path.exists(self.threat_log_file):
            try:
                with open(self.threat_log_file, 'r') as f:
                    return json.load(f)
            except:
                pass
        return []

    def _save_threat_log(self):
        """Save threat log"""
        try:
            with open(self.threat_log_file, 'w') as f:
                json.dump(self.threat_log[-500:], f, indent=2)
        except Exception as e:
            print(f"Error saving threat log: {e}")

    def log_activity(self, activity_type: str, details: Dict, user_id: Optional[str] = None):
        """
        Log an activity

        Args:
            activity_type: Type of activity (login, file_access, command, etc.)
            details: Activity details
            user_id: User performing activity
        """
        entry = {
            "timestamp": datetime.now().isoformat(),
            "type": activity_type,
            "user_id": user_id,
            "details": details,
            "risk_level": self._assess_risk(activity_type, details)
        }

        self.activity_log.append(entry)
        self.recent_activities.append(entry)

        if self.config["log_all_activities"]:
            self._save_activity_log()

        if entry["risk_level"] in ["high", "critical"]:
            self._handle_suspicious_activity(entry)

    def _assess_risk(self, activity_type: str, details: Dict) -> str:
        """Assess risk level of an activity"""
        if activity_type == "failed_authentication":
            recent_failures = sum(
                1 for a in self.recent_activities
                if a["type"] == "failed_authentication"
                and datetime.fromisoformat(a["timestamp"]) > datetime.now() - timedelta(minutes=5)
            )

            if recent_failures >= 3:
                return "critical"
            elif recent_failures >= 2:
                return "high"
            else:
                return "medium"

        elif activity_type == "system_command":
            dangerous_commands = ["rm -rf", "format", "del /f", "shutdown", "reboot"]
            if any(cmd in details.get("command", "").lower() for cmd in dangerous_commands):
                return "high"

        elif activity_type == "file_access":
            sensitive_paths = ["/etc/shadow", "/etc/passwd", "/.ssh", "password", "credential"]
            if any(path in details.get("path", "").lower() for path in sensitive_paths):
                return "high"

        return "low"

    def _handle_suspicious_activity(self, activity: Dict):
        """Handle detected suspicious activity"""
        threat_entry = {
            "timestamp": datetime.now().isoformat(),
            "threat_type": activity["type"],
            "risk_level": activity["risk_level"],
            "details": activity["details"],
            "user_id": activity.get("user_id"),
            "auto_response_taken": False
        }

        self.threat_log.append(threat_entry)
        self._save_threat_log()

        print(f"\n⚠️  SECURITY ALERT: {activity['type']}")
        print(f"   Risk Level: {activity['risk_level'].upper()}")
        print(f"   Details: {activity['details']}")
        print(f"   Time: {activity['timestamp']}")

        if self.config["auto_response_enabled"]:
            self._execute_auto_response(threat_entry)

    def _execute_auto_response(self, threat: Dict):
        """Execute automated response to threat"""
        if threat["risk_level"] == "critical":
            print(f"🚨 Critical threat detected! Taking automatic action...")

            if threat["threat_type"] == "failed_authentication":
                print("   Action: Temporary account lockout initiated")

        threat["auto_response_taken"] = True
        self._save_threat_log()

    def start_monitoring(self):
        """Start real-time activity monitoring"""
        if self.monitoring_active:
            return {"success": False, "message": "Monitoring already active"}

        self.monitoring_active = True
        self.monitor_thread = threading.Thread(target=self._monitoring_loop, daemon=True)
        self.monitor_thread.start()

        self.config["monitoring_enabled"] = True
        self._save_config()

        print("🛡️  Activity monitoring started")
        return {"success": True, "message": "Monitoring started"}

    def stop_monitoring(self):
        """Stop real-time monitoring"""
        self.monitoring_active = False
        self.config["monitoring_enabled"] = False
        self._save_config()

        print("⏸️  Activity monitoring stopped")
        return {"success": True, "message": "Monitoring stopped"}

    def _monitoring_loop(self):
        """Main monitoring loop"""
        print("🔍 Starting monitoring loop...")

        while self.monitoring_active:
            try:
                if self.config["process_monitoring"]:
                    self._check_processes()

                self._check_system_resources()

                time.sleep(30)

            except Exception as e:
                print(f"Monitoring error: {e}")
                time.sleep(60)

    def _check_processes(self):
        """Check running processes for suspicious activity"""
        try:
            blocked_processes = self.config.get("blocked_processes", [])
            suspicious_keywords = self.threat_patterns["unusual_process"]["suspicious_names"]

            for proc in psutil.process_iter(['pid', 'name', 'username']):
                try:
                    proc_name = proc.info['name'].lower()

                    if proc_name in blocked_processes:
                        self.log_activity(
                            "blocked_process_detected",
                            {
                                "process_name": proc_name,
                                "pid": proc.info['pid'],
                                "username": proc.info.get('username', 'unknown')
                            }
                        )

                    if any(keyword in proc_name for keyword in suspicious_keywords):
                        self.log_activity(
                            "suspicious_process",
                            {
                                "process_name": proc_name,
                                "pid": proc.info['pid'],
                                "username": proc.info.get('username', 'unknown')
                            }
                        )

                except (psutil.NoSuchProcess, psutil.AccessDenied):
                    continue

        except Exception as e:
            print(f"Process check error: {e}")

    def _check_system_resources(self):
        """Monitor system resource usage"""
        try:
            cpu_percent = psutil.cpu_percent(interval=1)
            memory_percent = psutil.virtual_memory().percent

            if cpu_percent > self.threat_patterns["high_cpu_usage"]["threshold"]:
                self.log_activity(
                    "high_cpu_usage",
                    {
                        "cpu_percent": cpu_percent,
                        "top_processes": self._get_top_cpu_processes()
                    }
                )

            if memory_percent > self.threat_patterns["high_memory_usage"]["threshold"]:
                self.log_activity(
                    "high_memory_usage",
                    {
                        "memory_percent": memory_percent,
                        "top_processes": self._get_top_memory_processes()
                    }
                )

        except Exception as e:
            print(f"Resource check error: {e}")

    def _get_top_cpu_processes(self, limit: int = 5) -> List[Dict]:
        """Get top CPU-consuming processes"""
        try:
            processes = []
            for proc in psutil.process_iter(['pid', 'name', 'cpu_percent']):
                try:
                    processes.append({
                        "pid": proc.info['pid'],
                        "name": proc.info['name'],
                        "cpu_percent": proc.info['cpu_percent']
                    })
                except (psutil.NoSuchProcess, psutil.AccessDenied):
                    pass

            processes.sort(key=lambda x: x['cpu_percent'], reverse=True)
            return processes[:limit]
        except:
            return []

    def _get_top_memory_processes(self, limit: int = 5) -> List[Dict]:
        """Get top memory-consuming processes"""
        try:
            processes = []
            for proc in psutil.process_iter(['pid', 'name', 'memory_percent']):
                try:
                    processes.append({
                        "pid": proc.info['pid'],
                        "name": proc.info['name'],
                        "memory_percent": proc.info['memory_percent']
                    })
                except (psutil.NoSuchProcess, psutil.AccessDenied):
                    pass

            processes.sort(key=lambda x: x['memory_percent'], reverse=True)
            return processes[:limit]
        except:
            return []

    def get_threat_summary(self, hours: int = 24) -> Dict:
        """
        Get summary of detected threats

        Args:
            hours: Time window for summary

        Returns:
            Dict with threat statistics
        """
        cutoff_time = datetime.now() - timedelta(hours=hours)

        recent_threats = [
            t for t in self.threat_log
            if datetime.fromisoformat(t["timestamp"]) > cutoff_time
        ]

        threat_types = Counter(t["threat_type"] for t in recent_threats)
        risk_levels = Counter(t["risk_level"] for t in recent_threats)

        return {
            "total_threats": len(recent_threats),
            "time_window_hours": hours,
            "threat_types": dict(threat_types),
            "risk_levels": dict(risk_levels),
            "critical_threats": len([t for t in recent_threats if t["risk_level"] == "critical"]),
            "high_threats": len([t for t in recent_threats if t["risk_level"] == "high"]),
            "recent_threats": recent_threats[-10:]
        }

    def get_activity_stats(self) -> Dict:
        """Get activity monitoring statistics"""
        total_activities = len(self.activity_log)
        total_threats = len(self.threat_log)

        recent_24h = [
            a for a in self.activity_log
            if datetime.fromisoformat(a["timestamp"]) > datetime.now() - timedelta(hours=24)
        ]

        activity_types = Counter(a["type"] for a in recent_24h)

        return {
            "monitoring_active": self.monitoring_active,
            "total_activities_logged": total_activities,
            "total_threats_detected": total_threats,
            "activities_24h": len(recent_24h),
            "activity_types_24h": dict(activity_types),
            "auto_response_enabled": self.config["auto_response_enabled"]
        }

    def add_blocked_process(self, process_name: str):
        """Add process to blocked list"""
        if process_name not in self.config["blocked_processes"]:
            self.config["blocked_processes"].append(process_name)
            self._save_config()
            print(f"🚫 Blocked process: {process_name}")

    def remove_blocked_process(self, process_name: str):
        """Remove process from blocked list"""
        if process_name in self.config["blocked_processes"]:
            self.config["blocked_processes"].remove(process_name)
            self._save_config()
            print(f"✅ Unblocked process: {process_name}")

    def enable_auto_response(self):
        """Enable automated threat response"""
        self.config["auto_response_enabled"] = True
        self._save_config()
        print("🤖 Auto-response enabled")

    def disable_auto_response(self):
        """Disable automated threat response"""
        self.config["auto_response_enabled"] = False
        self._save_config()
        print("⚠️  Auto-response disabled")


if __name__ == "__main__":
    print("🛡️  Activity Monitoring System")
    print("=" * 50)

    monitor = ActivityMonitoringSystem()

    print("\n📊 System Status:")
    stats = monitor.get_activity_stats()
    print(f"Monitoring active: {stats['monitoring_active']}")
    print(f"Total activities: {stats['total_activities_logged']}")
    print(f"Total threats: {stats['total_threats_detected']}")
    print(f"Auto-response: {stats['auto_response_enabled']}")

    print("\n" + "=" * 50)
    print("✅ Activity monitoring system ready!")

modules/development/sandbox_mode.py.content:
"""
🧪 Sandbox Mode
Safely test automations without affecting the actual system
"""

import os
import json
import shutil
import tempfile
from datetime import datetime
from typing import Dict, List, Any, Optional
from pathlib import Path
import subprocess

class SandboxMode:
    """
    Isolated sandbox environment for testing automations safely
    Features:
    - Virtual file system
    - Command logging without execution
    - Undo/rollback capabilities
    - Safe testing environment
    - Execution simulation
    """

    def __init__(self):
        self.sandbox_dir = "sandbox_environment"
        self.virtual_fs_dir = os.path.join(self.sandbox_dir, "virtual_fs")
        self.log_file = os.path.join(self.sandbox_dir, "sandbox_log.json")
        self.config_file = os.path.join(self.sandbox_dir, "sandbox_config.json")
        self.session_file = os.path.join(self.sandbox_dir, "current_session.json")

        os.makedirs(self.sandbox_dir, exist_ok=True)
        os.makedirs(self.virtual_fs_dir, exist_ok=True)

        self.config = self._load_config()
        self.session = self._load_session()
        self.command_log = []

        self.sandbox_active = False
        self.safe_commands = ["echo", "ls", "pwd", "cat", "grep", "find", "head", "tail"]
        self.blocked_commands = ["rm -rf", "format", "del /s", "shutdown", "reboot", "kill -9"]

    def _load_config(self) -> Dict:
        """Load sandbox configuration"""
        if os.path.exists(self.config_file):
            try:
                with open(self.config_file, 'r') as f:
                    return json.load(f)
            except:
                pass

        return {
            "allow_file_operations": True,
            "allow_network_operations": False,
            "allow_system_commands": False,
            "log_all_actions": True,
            "auto_rollback_on_error": True,
            "max_session_duration_minutes": 60
        }

    def _save_config(self):
        """Save sandbox configuration"""
        try:
            with open(self.config_file, 'w') as f:
                json.dump(self.config, f, indent=2)
        except Exception as e:
            print(f"Error saving config: {e}")

    def _load_session(self) -> Dict:
        """Load current sandbox session"""
        if os.path.exists(self.session_file):
            try:
                with open(self.session_file, 'r') as f:
                    return json.load(f)
            except:
                pass

        return {
            "session_id": None,
            "start_time": None,
            "end_time": None,
            "actions_performed": [],
            "status": "inactive"
        }

    def _save_session(self):
        """Save current session"""
        try:
            with open(self.session_file, 'w') as f:
                json.dump(self.session, f, indent=2)
        except Exception as e:
            print(f"Error saving session: {e}")

    def start_sandbox(self, session_name: Optional[str] = None) -> Dict:
        """
        Start a new sandbox session

        Args:
            session_name: Optional name for the session

        Returns:
            Dict with session info
        """
        try:
            if self.sandbox_active:
                return {
                    "success": False,
                    "message": "Sandbox already active"
                }

            session_id = session_name or f"sandbox_{datetime.now().strftime('%Y%m%d_%H%M%S')}"

            session_dir = os.path.join(self.virtual_fs_dir, session_id)
            os.makedirs(session_dir, exist_ok=True)

            self.session = {
                "session_id": session_id,
                "start_time": datetime.now().isoformat(),
                "end_time": None,
                "session_dir": session_dir,
                "actions_performed": [],
                "status": "active"
            }

            self.sandbox_active = True
            self.command_log = []

            self._save_session()

            print(f"🧪 Sandbox session started: {session_id}")
            print(f"   Working directory: {session_dir}")
            print(f"   Mode: Safe testing environment")

            return {
                "success": True,
                "session_id": session_id,
                "session_dir": session_dir,
                "message": "Sandbox session started successfully"
            }

        except Exception as e:
            return {
                "success": False,
                "message": f"Error starting sandbox: {str(e)}"
            }

    def execute_command(self, command: str, simulate: bool = True) -> Dict:
        """
        Execute or simulate a command in sandbox

        Args:
            command: Command to execute
            simulate: If True, only simulate (don't actually execute)

        Returns:
            Dict with execution result
        """
        if not self.sandbox_active:
            return {
                "success": False,
                "message": "Sandbox not active. Start a session first."
            }

        for blocked_cmd in self.blocked_commands:
            if blocked_cmd in command.lower():
                return {
                    "success": False,
                    "message": f"Blocked command detected: {blocked_cmd}",
                    "severity": "critical"
                }

        action = {
            "timestamp": datetime.now().isoformat(),
            "command": command,
            "simulated": simulate,
            "status": "pending"
        }

        try:
            if simulate:
                print(f"🎬 SIMULATING: {command}")
                result = f"[SIMULATED] Command would execute: {command}"
                action["status"] = "simulated"
                action["result"] = result
            else:
                if any(safe_cmd in command for safe_cmd in self.safe_commands):
                    print(f"▶️  EXECUTING SAFE: {command}")

                    result = subprocess.run(
                        command,
                        shell=True,
                        capture_output=True,
                        text=True,
                        timeout=10,
                        cwd=self.session["session_dir"]
                    )

                    action["status"] = "executed"
                    action["return_code"] = result.returncode
                    action["stdout"] = result.stdout
                    action["stderr"] = result.stderr
                else:
                    return {
                        "success": False,
                        "message": "Command not in safe list. Use simulate=True or add to safe commands."
                    }

            self.command_log.append(action)
            self.session["actions_performed"].append(action)
            self._save_session()

            return {
                "success": True,
                "action": action,
                "message": "Command processed successfully"
            }

        except subprocess.TimeoutExpired:
            action["status"] = "timeout"
            return {
                "success": False,
                "message": "Command timed out"
            }
        except Exception as e:
            action["status"] = "error"
            action["error"] = str(e)
            return {
                "success": False,
                "message": f"Execution error: {str(e)}"
            }

    def create_virtual_file(self, filename: str, content: str) -> Dict:
        """
        Create a file in the sandbox virtual filesystem

        Args:
            filename: Name of file to create
            content: File content

        Returns:
            Dict with creation result
        """
        if not self.sandbox_active:
            return {
                "success": False,
                "message": "Sandbox not active"
            }

        try:
            file_path = os.path.join(self.session["session_dir"], filename)

            with open(file_path, 'w') as f:
                f.write(content)

            action = {
                "timestamp": datetime.now().isoformat(),
                "action_type": "create_file",
                "filename": filename,
                "file_path": file_path,
                "size": len(content)
            }

            self.session["actions_performed"].append(action)
            self._save_session()

            print(f"📄 Created virtual file: {filename}")

            return {
                "success": True,
                "file_path": file_path,
                "message": f"File created: {filename}"
            }

        except Exception as e:
            return {
                "success": False,
                "message": f"Error creating file: {str(e)}"
            }

    def read_virtual_file(self, filename: str) -> Dict:
        """Read a file from the sandbox virtual filesystem"""
        if not self.sandbox_active:
            return {
                "success": False,
                "message": "Sandbox not active"
            }

        try:
            file_path = os.path.join(self.session["session_dir"], filename)

            if not os.path.exists(file_path):
                return {
                    "success": False,
                    "message": f"File not found: {filename}"
                }

            with open(file_path, 'r') as f:
                content = f.read()

            return {
                "success": True,
                "content": content,
                "file_path": file_path
            }

        except Exception as e:
            return {
                "success": False,
                "message": f"Error reading file: {str(e)}"
            }

    def list_virtual_files(self) -> Dict:
        """List all files in the sandbox virtual filesystem"""
        if not self.sandbox_active:
            return {
                "success": False,
                "message": "Sandbox not active"
            }

        try:
            session_dir = self.session["session_dir"]
            files = []

            for root, dirs, filenames in os.walk(session_dir):
                for filename in filenames:
                    file_path = os.path.join(root, filename)
                    rel_path = os.path.relpath(file_path, session_dir)

                    stat = os.stat(file_path)
                    files.append({
                        "name": filename,
                        "path": rel_path,
                        "size": stat.st_size,
                        "modified": datetime.fromtimestamp(stat.st_mtime).isoformat()
                    })

            return {
                "success": True,
                "files": files,
                "count": len(files)
            }

        except Exception as e:
            return {
                "success": False,
                "message": f"Error listing files: {str(e)}"
            }

    def get_session_log(self) -> Dict:
        """Get log of all actions in current session"""
        if not self.sandbox_active:
            return {
                "success": False,
                "message": "No active session"
            }

        return {
            "success": True,
            "session_id": self.session["session_id"],
            "start_time": self.session["start_time"],
            "actions_count": len(self.session["actions_performed"]),
            "actions": self.session["actions_performed"]
        }

    def rollback_session(self) -> Dict:
        """Rollback all changes in current session"""
        if not self.sandbox_active:
            return {
                "success": False,
                "message": "No active session to rollback"
            }

        try:
            session_dir = self.session["session_dir"]

            if os.path.exists(session_dir):
                shutil.rmtree(session_dir)
                os.makedirs(session_dir, exist_ok=True)

            print(f"🔄 Session rolled back: {self.session['session_id']}")

            return {
                "success": True,
                "message": "Session rolled back successfully"
            }

        except Exception as e:
            return {
                "success": False,
                "message": f"Rollback error: {str(e)}"
            }

    def end_sandbox(self, keep_session: bool = False) -> Dict:
        """
        End the current sandbox session

        Args:
            keep_session: Keep session data after ending

        Returns:
            Dict with session summary
        """
        if not self.sandbox_active:
            return {
                "success": False,
                "message": "No active sandbox session"
            }

        try:
            self.session["end_time"] = datetime.now().isoformat()
            self.session["status"] = "completed"

            summary = {
                "session_id": self.session["session_id"],
                "duration": self._calculate_duration(),
                "actions_performed": len(self.session["actions_performed"]),
                "files_created": len([a for a in self.session["actions_performed"] if a.get("action_type") == "create_file"]),
                "commands_executed": len([a for a in self.session["actions_performed"] if a.get("command")])
            }

            self._save_session()

            if not keep_session:
                session_dir = self.session["session_dir"]
                if os.path.exists(session_dir):
                    shutil.rmtree(session_dir)

            self.sandbox_active = False

            print(f"🏁 Sandbox session ended")
            print(f"   Duration: {summary['duration']}")
            print(f"   Actions: {summary['actions_performed']}")

            return {
                "success": True,
                "summary": summary,
                "message": "Sandbox session ended successfully"
            }

        except Exception as e:
            return {
                "success": False,
                "message": f"Error ending session: {str(e)}"
            }

    def _calculate_duration(self) -> str:
        """Calculate session duration"""
        try:
            start = datetime.fromisoformat(self.session["start_time"])
            end = datetime.fromisoformat(self.session["end_time"]) if self.session["end_time"] else datetime.now()

            duration = end - start
            minutes = int(duration.total_seconds() / 60)
            seconds = int(duration.total_seconds() % 60)

            return f"{minutes}m {seconds}s"
        except:
            return "Unknown"

    def get_sandbox_status(self) -> Dict:
        """Get current sandbox status"""
        return {
            "active": self.sandbox_active,
            "session_id": self.session.get("session_id"),
            "start_time": self.session.get("start_time"),
            "actions_count": len(self.session.get("actions_performed", [])),
            "allow_file_operations": self.config["allow_file_operations"],
            "allow_system_commands": self.config["allow_system_commands"]
        }


if __name__ == "__main__":
    print("🧪 Sandbox Mode")
    print("=" * 50)

    sandbox = SandboxMode()

    print("\n📊 Sandbox Status:")
    status = sandbox.get_sandbox_status()
    print(f"Active: {status['active']}")
    print(f"Session ID: {status['session_id']}")

    print("\n" + "=" * 50)
    print("✅ Sandbox mode ready!")

modules/smart_features/workflow_template.content:
"""
Workflow Templates Module
Save and reuse common workflows
"""

import json
import os
from typing import List, Dict
from datetime import datetime

class WorkflowManager:
    """Manages workflow templates"""

    def __init__(self, templates_file: str = "workflow_templates.json"):
        self.templates_file = templates_file
        self.templates: Dict[str, Dict] = {}
        self.load_templates()

    def save_workflow(self, name: str, steps: List[Dict], description: str = "") -> bool:
        """Save a workflow template"""
        try:
            self.templates[name] = {
                "name": name,
                "description": description,
                "steps": steps,
                "created": datetime.now().isoformat(),
                "usage_count": 0
            }
            self.save_templates()
            return True
        except Exception:
            return False

    def load_workflow(self, name: str) -> Dict:
        """Load a workflow template"""
        workflow = self.templates.get(name)
        if workflow:
            workflow["usage_count"] += 1
            self.save_templates()
        return workflow

    def list_workflows(self) -> List[Dict]:
        """List all workflow templates"""
        return [
            {
                "name": w["name"],
                "description": w["description"],
                "steps_count": len(w["steps"]),
                "usage_count": w["usage_count"]
            }
            for w in self.templates.values()
        ]

    def delete_workflow(self, name: str) -> bool:
        """Delete a workflow template"""
        if name in self.templates:
            del self.templates[name]
            self.save_templates()
            return True
        return False

    def get_popular_workflows(self, limit: int = 5) -> List[Dict]:
        """Get most used workflows"""
        workflows = list(self.templates.values())
        workflows.sort(key=lambda x: x["usage_count"], reverse=True)
        return workflows[:limit]

    def save_templates(self):
        """Save templates to file"""
        try:
            with open(self.templates_file, "w") as f:
                json.dump(self.templates, f, indent=2)
        except Exception:
            pass

    def load_templates(self):
        """Load templates from file"""
        try:
            if os.path.exists(self.templates_file):
                with open(self.templates_file, "r") as f:
                    self.templates = json.load(f)
        except Exception:
            pass

    def create_default_templates(self):
        """Create some default useful templates"""
        defaults = [
            {
                "name": "morning_routine",
                "description": "Open common apps for morning work",
                "steps": [
                    {"action": "open_app", "parameters": {"app_name": "chrome"}},
                    {"action": "wait", "parameters": {"seconds": 2}},
                    {"action": "open_app", "parameters": {"app_name": "notepad"}}
                ]
            },
            {
                "name": "take_notes",
                "description": "Open notepad and create dated note file",
                "steps": [
                    {"action": "open_app", "parameters": {"app_name": "notepad"}},
                    {"action": "wait", "parameters": {"seconds": 1}},
                    {"action": "type_text", "parameters": {"text": f"Notes - {datetime.now().strftime('%Y-%m-%d')}\n\n"}}
                ]
            }
        ]

        for template in defaults:
            if template["name"] not in self.templates:
                self.save_workflow(
                    template["name"],
                    template["steps"],
                    template["description"]
                )

