"""
Smart Break Suggestions - AI recommends optimal activity type for breaks
Personalized based on time of day, energy level, and work intensity
"""

import json
from datetime import datetime, timedelta
from pathlib import Path
import random


class SmartBreakSuggester:
    """Suggests optimal break activities based on context"""

    def __init__(self, gemini_model=None):
        self.script_dir = Path(__file__).parent.absolute()
        self.data_dir = self.script_dir / "productivity_data"
        self.data_dir.mkdir(exist_ok=True)

        self.break_history_file = self.data_dir / "break_history.json"
        self.gemini = gemini_model

        # Break activity categories
        self.break_activities = {
            "physical": [
                {"name": "Walk", "duration": 5, "energy_gain": 15, "description": "Take a 5-minute walk around your space"},
                {"name": "Stretch", "duration": 3, "energy_gain": 10, "description": "Full body stretching routine"},
                {"name": "Exercise", "duration": 10, "energy_gain": 25, "description": "Quick exercise (jumping jacks, push-ups)"},
                {"name": "Yoga", "duration": 10, "energy_gain": 20, "description": "Simple yoga poses for desk workers"}
            ],
            "mental": [
                {"name": "Meditate", "duration": 5, "energy_gain": 15, "description": "5-minute mindfulness meditation"},
                {"name": "Deep Breathing", "duration": 2, "energy_gain": 8, "description": "Box breathing or 4-7-8 technique"},
                {"name": "Music", "duration": 5, "energy_gain": 10, "description": "Listen to calming music"},
                {"name": "Nature Sounds", "duration": 3, "energy_gain": 8, "description": "Close eyes and listen to nature"}
            ],
            "social": [
                {"name": "Chat", "duration": 5, "energy_gain": 12, "description": "Quick chat with a colleague or friend"},
                {"name": "Video Call", "duration": 10, "energy_gain": 15, "description": "Short video call with loved ones"},
                {"name": "Team Check-in", "duration": 5, "energy_gain": 10, "description": "Quick team bonding moment"}
            ],
            "refreshment": [
                {"name": "Water", "duration": 1, "energy_gain": 5, "description": "Drink a glass of water"},
                {"name": "Snack", "duration": 3, "energy_gain": 8, "description": "Healthy snack (fruit, nuts)"},
                {"name": "Coffee/Tea", "duration": 5, "energy_gain": 10, "description": "Make fresh coffee or tea"},
                {"name": "Meal", "duration": 15, "energy_gain": 20, "description": "Proper meal break"}
            ],
            "creative": [
                {"name": "Doodle", "duration": 5, "energy_gain": 10, "description": "Free drawing or doodling"},
                {"name": "Read", "duration": 10, "energy_gain": 12, "description": "Read something non-work related"},
                {"name": "Journal", "duration": 5, "energy_gain": 10, "description": "Quick journaling or reflection"},
                {"name": "Puzzle", "duration": 5, "energy_gain": 8, "description": "Quick puzzle or brain teaser"}
            ],
            "sensory": [
                {"name": "Fresh Air", "duration": 3, "energy_gain": 10, "description": "Step outside for fresh air"},
                {"name": "Sunlight", "duration": 5, "energy_gain": 12, "description": "Get natural sunlight exposure"},
                {"name": "Eye Rest", "duration": 2, "energy_gain": 8, "description": "20-20-20 rule: look 20ft away for 20 seconds"},
                {"name": "Cold Water Face Wash", "duration": 2, "energy_gain": 10, "description": "Splash cold water on face"}
            ]
        }

        self.last_break_time = None
        self.breaks_today = 0

    def suggest_break(self, energy_level=50, work_intensity="medium", time_since_last_break=60):
        """Suggest optimal break activity based on context"""
        hour = datetime.now().hour

        # Determine break category based on context
        if energy_level < 30:
            # Very low energy - physical or refreshment
            preferred_categories = ["physical", "refreshment", "sensory"]
        elif energy_level < 50:
            # Moderate energy - mental or light physical
            preferred_categories = ["mental", "physical", "sensory"]
        elif work_intensity == "high":
            # High intensity work - mental relaxation
            preferred_categories = ["mental", "creative", "sensory"]
        else:
            # Normal - any category
            preferred_categories = list(self.break_activities.keys())

        # Time-based adjustments
        if hour < 10:
            # Morning - energizing activities
            preferred_categories = ["physical", "refreshment"]
        elif 12 <= hour < 14:
            # Lunch time - meal/refreshment
            preferred_categories = ["refreshment", "social"]
        elif hour >= 18:
            # Evening - wind down
            preferred_categories = ["mental", "creative"]

        # Select random category from preferred
        category = random.choice(preferred_categories)
        activities = self.break_activities[category]

        # Select activity based on available time
        if time_since_last_break > 120:
            # Long work session - longer break
            suitable = [a for a in activities if a["duration"] >= 5]
        else:
            # Recent break - quick activity
            suitable = [a for a in activities if a["duration"] <= 5]

        activity = random.choice(suitable if suitable else activities)

        # Get AI-enhanced suggestion if available
        ai_insight = self._get_ai_break_suggestion(energy_level, category, activity["name"])

        return {
            "category": category,
            "activity": activity["name"],
            "duration_minutes": activity["duration"],
            "description": activity["description"],
            "expected_energy_gain": activity["energy_gain"],
            "ai_tip": ai_insight,
            "urgency": "high" if energy_level < 30 else "medium" if energy_level < 50 else "low"
        }

    def _get_ai_break_suggestion(self, energy_level, category, activity_name):
        """Get AI-enhanced break suggestion"""
        if not self.gemini:
            return f"Try {activity_name} to recharge!"

        try:
            prompt = f"""
            User has energy level of {energy_level}/100.
            Suggesting a {category} break: {activity_name}.

            Give ONE SENTENCE of encouraging, specific advice for this break.
            Be motivating and practical.
            """

            response = self.gemini.generate_content(prompt)
            return response.text.strip()
        except:
            return f"Perfect time for {activity_name}!"

    def log_break(self, activity, duration_minutes, energy_before, energy_after):
        """Log break activity and effectiveness"""
        try:
            history = []
            if self.break_history_file.exists():
                with open(self.break_history_file, 'r') as f:
                    history = json.load(f)

            entry = {
                "timestamp": datetime.now().isoformat(),
                "activity": activity,
                "duration_minutes": duration_minutes,
                "energy_before": energy_before,
                "energy_after": energy_after,
                "energy_gain": energy_after - energy_before,
                "hour_of_day": datetime.now().hour
            }

            history.append(entry)
            history = history[-500:]  # Keep last 500

            with open(self.break_history_file, 'w') as f:
                json.dump(history, f, indent=2)

            self.last_break_time = datetime.now()
            self.breaks_today += 1

            return {"success": True}
        except Exception as e:
            return {"success": False, "error": str(e)}

    def get_break_analytics(self, days=7):
        """Analyze break effectiveness"""
        try:
            if not self.break_history_file.exists():
                return {"success": False, "message": "No break history"}

            with open(self.break_history_file, 'r') as f:
                history = json.load(f)

            cutoff = datetime.now() - timedelta(days=days)
            recent = [
                b for b in history
                if datetime.fromisoformat(b["timestamp"]) > cutoff
            ]

            if not recent:
                return {"success": False, "message": "No recent breaks"}

            # Calculate effectiveness by activity
            activity_stats = {}
            for entry in recent:
                activity = entry["activity"]
                if activity not in activity_stats:
                    activity_stats[activity] = {"count": 0, "total_gain": 0}
                activity_stats[activity]["count"] += 1
                activity_stats[activity]["total_gain"] += entry["energy_gain"]

            # Calculate average gain per activity
            for activity in activity_stats:
                avg_gain = activity_stats[activity]["total_gain"] / activity_stats[activity]["count"]
                activity_stats[activity]["avg_energy_gain"] = round(avg_gain, 1)

            # Best activity
            best_activity = max(activity_stats.items(), key=lambda x: x[1]["avg_energy_gain"])[0] if activity_stats else None

            return {
                "success": True,
                "days": days,
                "total_breaks": len(recent),
                "avg_breaks_per_day": len(recent) / days,
                "activity_stats": activity_stats,
                "most_effective": best_activity
            }
        except Exception as e:
            return {"success": False, "error": str(e)}


# Singleton instance
_break_suggester = None

def get_break_suggester(gemini_model=None):
    """Get or create break suggester instance"""
    global _break_suggester
    if _break_suggester is None:
        _break_suggester = SmartBreakSuggester(gemini_model)
    return _break_suggester

modules/automation/desktop_controller_ad.content:
"""
🖥️ Advanced Desktop Controller - Complete Desktop Control
Full system control including windows, displays, keyboard macros, and system-wide automation
"""

import psutil
import os
import json
import subprocess
import time
from datetime import datetime

try:
    import pyautogui
    PYAUTOGUI_AVAILABLE = True
except Exception:
    PYAUTOGUI_AVAILABLE = False
    pyautogui = None

class AdvancedDesktopController:
    """Comprehensive desktop control for complete system automation"""

    def __init__(self):
        self.macro_file = "desktop_macros.json"
        self.macros = self.load_macros()

        # PyAutoGUI safety settings
        if PYAUTOGUI_AVAILABLE and pyautogui:
            pyautogui.FAILSAFE = True
            pyautogui.PAUSE = 0.1

    def load_macros(self):
        """Load saved macros"""
        if os.path.exists(self.macro_file):
            try:
                with open(self.macro_file, 'r') as f:
                    return json.load(f)
            except:
                pass
        return {}

    def save_macros(self):
        """Save macros"""
        try:
            with open(self.macro_file, 'w') as f:
                json.dump(self.macros, f, indent=2)
        except:
            pass

    # ===== WINDOW MANAGEMENT =====

    def list_windows(self):
        """List all open windows and applications"""
        output = "\n" + "="*60 + "\n"
        output += "🪟 OPEN WINDOWS & APPLICATIONS\n"
        output += "="*60 + "\n\n"

        try:
            windows = []
            for proc in psutil.process_iter(['pid', 'name', 'create_time']):
                try:
                    info = proc.info
                    windows.append({
                        'pid': info['pid'],
                        'name': info['name'],
                        'uptime': time.time() - info['create_time']
                    })
                except:
                    pass

            # Group by name
            app_counts = {}
            for w in windows:
                name = w['name']
                if name not in app_counts:
                    app_counts[name] = []
                app_counts[name].append(w)

            # Display
            for app_name in sorted(app_counts.keys()):
                instances = app_counts[app_name]
                output += f"📱 {app_name} ({len(instances)} instance{'s' if len(instances) > 1 else ''})\n"
                for inst in instances[:3]:  # Show max 3
                    uptime_min = int(inst['uptime'] / 60)
                    output += f"   PID: {inst['pid']} - Running: {uptime_min}m\n"

            output += "\n" + "="*60 + "\n"
            output += f"Total Applications: {len(app_counts)}\n"
            output += "="*60 + "\n"

        except Exception as e:
            output += f"Error listing windows: {str(e)}\n"

        return output

    def minimize_window(self, app_name):
        """Minimize a window (platform specific)"""
        try:
            if os.name == 'nt':  # Windows
                import win32gui
                import win32con

                def callback(hwnd, hwnds):
                    if win32gui.IsWindowVisible(hwnd):
                        title = win32gui.GetWindowText(hwnd)
                        if app_name.lower() in title.lower():
                            win32gui.ShowWindow(hwnd, win32con.SW_MINIMIZE)
                            hwnds.append(hwnd)
                    return True

                hwnds = []
                win32gui.EnumWindows(callback, hwnds)

                if hwnds:
                    return f"✅ Minimized {len(hwnds)} window(s) for '{app_name}'"
                else:
                    return f"❌ No window found for '{app_name}'"
            else:
                # Linux/Mac - use wmctrl if available
                result = subprocess.run(
                    ['wmctrl', '-r', app_name, '-b', 'add,hidden'],
                    capture_output=True,
                    text=True
                )
                if result.returncode == 0:
                    return f"✅ Minimized window '{app_name}'"
                else:
                    return f"❌ Could not minimize '{app_name}'. Install wmctrl for window control."
        except Exception as e:
            return f"Error: {str(e)}\nNote: Install pywin32 (Windows) or wmctrl (Linux) for window management"

    def maximize_window(self, app_name):
        """Maximize a window"""
        try:
            if os.name == 'nt':  # Windows
                import win32gui
                import win32con

                def callback(hwnd, hwnds):
                    if win32gui.IsWindowVisible(hwnd):
                        title = win32gui.GetWindowText(hwnd)
                        if app_name.lower() in title.lower():
                            win32gui.ShowWindow(hwnd, win32con.SW_MAXIMIZE)
                            hwnds.append(hwnd)
                    return True

                hwnds = []
                win32gui.EnumWindows(callback, hwnds)

                if hwnds:
                    return f"✅ Maximized {len(hwnds)} window(s) for '{app_name}'"
                else:
                    return f"❌ No window found for '{app_name}'"
            else:
                result = subprocess.run(
                    ['wmctrl', '-r', app_name, '-b', 'add,maximized_vert,maximized_horz'],
                    capture_output=True
                )
                if result.returncode == 0:
                    return f"✅ Maximized window '{app_name}'"
                else:
                    return f"❌ Could not maximize '{app_name}'"
        except Exception as e:
            return f"Error: {str(e)}"

    def close_window(self, app_name):
        """Close a specific window/application"""
        try:
            killed = 0
            for proc in psutil.process_iter(['name']):
                try:
                    if app_name.lower() in proc.info['name'].lower():
                        proc.kill()
                        killed += 1
                except:
                    pass

            if killed > 0:
                return f"✅ Closed {killed} instance(s) of '{app_name}'"
            else:
                return f"❌ No application found matching '{app_name}'"
        except Exception as e:
            return f"Error: {str(e)}"

    def switch_to_window(self, app_name):
        """Switch focus to a specific window"""
        try:
            if os.name == 'nt':  # Windows
                import win32gui

                def callback(hwnd, hwnds):
                    if win32gui.IsWindowVisible(hwnd):
                        title = win32gui.GetWindowText(hwnd)
                        if app_name.lower() in title.lower():
                            win32gui.SetForegroundWindow(hwnd)
                            hwnds.append(hwnd)
                            return False  # Stop after first match
                    return True

                hwnds = []
                win32gui.EnumWindows(callback, hwnds)

                if hwnds:
                    return f"✅ Switched to '{app_name}'"
                else:
                    return f"❌ Window '{app_name}' not found"
            else:
                result = subprocess.run(
                    ['wmctrl', '-a', app_name],
                    capture_output=True
                )
                if result.returncode == 0:
                    return f"✅ Switched to '{app_name}'"
                else:
                    return f"❌ Could not switch to '{app_name}'"
        except Exception as e:
            return f"Error: {str(e)}"

    # ===== DISPLAY CONTROL =====

    def get_screen_info(self):
        """Get information about displays/monitors"""
        output = "\n" + "="*60 + "\n"
        output += "🖥️ DISPLAY INFORMATION\n"
        output += "="*60 + "\n\n"

        try:
            width, height = pyautogui.size()
            output += f"Primary Screen Resolution: {width}x{height}\n"
            output += f"Current Mouse Position: {pyautogui.position()}\n\n"

            # Try to get monitor count (platform specific)
            if os.name == 'nt':
                try:
                    import win32api
                    monitors = win32api.EnumDisplayMonitors()
                    output += f"Number of Monitors: {len(monitors)}\n\n"
                    for i, monitor in enumerate(monitors, 1):
                        output += f"Monitor {i}: {monitor[2]}\n"
                except:
                    output += "Install pywin32 for detailed monitor info\n"

            output += "\n" + "="*60 + "\n"
        except Exception as e:
            output += f"Error: {str(e)}\n"

        return output

    # ===== MACRO RECORDING =====

    def record_macro(self, macro_name, duration=10):
        """Record mouse and keyboard actions as a macro"""
        output = f"\n🎬 Recording macro '{macro_name}' for {duration} seconds...\n"
        output += "Move your mouse and perform actions now!\n\n"

        try:
            start_time = time.time()
            actions = []
            last_pos = pyautogui.position()

            while time.time() - start_time < duration:
                current_pos = pyautogui.position()

                # Record mouse movements
                if current_pos != last_pos:
                    actions.append({
                        'type': 'move',
                        'x': current_pos.x,
                        'y': current_pos.y,
                        'time': time.time() - start_time
                    })
                    last_pos = current_pos

                time.sleep(0.1)

            self.macros[macro_name] = actions
            self.save_macros()

            output += f"✅ Macro '{macro_name}' recorded with {len(actions)} actions!\n"
        except Exception as e:
            output += f"Error: {str(e)}\n"

        return output

    def play_macro(self, macro_name, speed=1.0):
        """Play a recorded macro"""
        if macro_name not in self.macros:
            return f"❌ Macro '{macro_name}' not found"

        try:
            actions = self.macros[macro_name]
            start_time = time.time()

            for action in actions:
                # Wait for the correct time
                target_time = action['time'] / speed
                while time.time() - start_time < target_time:
                    time.sleep(0.01)

                if action['type'] == 'move':
                    pyautogui.moveTo(action['x'], action['y'])
                elif action['type'] == 'click':
                    pyautogui.click()

            return f"✅ Macro '{macro_name}' played successfully!"
        except Exception as e:
            return f"Error: {str(e)}"

    def list_macros(self):
        """List all recorded macros"""
        if not self.macros:
            return "📋 No macros recorded yet."

        output = "\n" + "="*60 + "\n"
        output += "🎬 RECORDED MACROS\n"
        output += "="*60 + "\n\n"

        for name, actions in self.macros.items():
            duration = actions[-1]['time'] if actions else 0
            output += f"• {name} - {len(actions)} actions, {duration:.1f}s duration\n"

        output += "\n" + "="*60 + "\n"

        return output

    #===== ADVANCED AUTOMATION =====

    def create_global_shortcut(self, shortcut_name, keys, action):
        """Create a system-wide keyboard shortcut (requires elevated permissions)"""
        # This is a placeholder - actual implementation requires platform-specific libraries
        return f"💡 Global shortcut feature requires platform-specific setup.\n" \
               f"On Windows: Use pywin32 or pynput\n" \
               f"On Linux: Use python-xlib or pynput\n" \
               f"On Mac: Use pyobjc"

    def auto_organize_desktop(self):
        """Automatically organize desktop icons"""
        desktop = os.path.expanduser("~/Desktop")

        if not os.path.exists(desktop):
            return "❌ Desktop folder not found"

        try:
            files = os.listdir(desktop)
            organized = 0

            # Create folders by type
            folders = {
                'Images': ['.png', '.jpg', '.jpeg', '.gif', '.bmp'],
                'Documents': ['.pdf', '.doc', '.docx', '.txt', '.md'],
                'Spreadsheets': ['.xls', '.xlsx', '.csv'],
                'Videos': ['.mp4', '.avi', '.mkv', '.mov'],
                'Archives': ['.zip', '.rar', '.7z', '.tar', '.gz']
            }

            for filename in files:
                filepath = os.path.join(desktop, filename)

                if os.path.isfile(filepath):
                    _, ext = os.path.splitext(filename)
                    ext = ext.lower()

                    for folder, extensions in folders.items():
                        if ext in extensions:
                            folder_path = os.path.join(desktop, folder)
                            os.makedirs(folder_path, exist_ok=True)

                            new_path = os.path.join(folder_path, filename)
                            os.rename(filepath, new_path)
                            organized += 1
                            break

            return f"✅ Organized {organized} file(s) on your desktop!"
        except Exception as e:
            return f"Error: {str(e)}"

    def take_window_screenshot(self, app_name):
        """Take screenshot of a specific window"""
        try:
            # Switch to window first
            self.switch_to_window(app_name)
            time.sleep(0.5)

            # Take screenshot
            filename = f"screenshot_{app_name}_{datetime.now().strftime('%Y%m%d_%H%M%S')}.png"
            screenshot = pyautogui.screenshot()
            screenshot.save(filename)

            return f"✅ Screenshot saved as '{filename}'"
        except Exception as e:
            return f"Error: {str(e)}"

modules/intelligence/conversation_memory.content:
"""
Conversation Memory Module
Tracks conversation history and provides context awareness
"""

import json
import os
from datetime import datetime
from typing import List, Dict

class ConversationMemory:
    """Manages conversation history and context"""

    def __init__(self, max_history: int = 50):
        self.max_history = max_history
        self.history: List[Dict] = []
        self.context: Dict = {}
        self.load_history()

    def add_command(self, user_input: str, result: Dict, command_dict: Dict = None):
        """Add a command to history"""
        entry = {
            "timestamp": datetime.now().isoformat(),
            "user_input": user_input,
            "command": command_dict,
            "result": {
                "success": result.get("success"),
                "message": result.get("message", "")[:200]
            }
        }

        self.history.append(entry)

        if len(self.history) > self.max_history:
            self.history = self.history[-self.max_history:]

        self.update_context(entry)
        self.save_history()

    def update_context(self, entry: Dict):
        """Update context based on recent activity"""
        if entry["result"]["success"]:
            last_action = entry.get("command", {}).get("action", "")
            self.context["last_successful_action"] = last_action
            self.context["last_command"] = entry["user_input"]

            if "generated_code" in entry["result"]:
                self.context["last_generated_code"] = entry["result"]["generated_code"][:500]

    def get_recent_history(self, count: int = 10) -> List[Dict]:
        """Get recent command history"""
        return self.history[-count:] if self.history else []

    def get_context_summary(self) -> str:
        """Get a summary of current context"""
        if not self.history:
            return "No previous commands"

        recent = self.get_recent_history(5)
        summary = f"Recent commands ({len(recent)}):\n"

        for entry in recent:
            status = "✅" if entry["result"]["success"] else "❌"
            summary += f"  {status} {entry['user_input'][:50]}\n"

        return summary

    def search_history(self, query: str) -> List[Dict]:
        """Search command history"""
        query_lower = query.lower()
        results = []

        for entry in self.history:
            if query_lower in entry["user_input"].lower():
                results.append(entry)

        return results

    def get_last_code(self) -> str:
        """Get the last generated code"""
        return self.context.get("last_generated_code", "")

    def clear_history(self):
        """Clear all history"""
        self.history = []
        self.context = {}
        self.save_history()

    def save_history(self):
        """Save history to file"""
        try:
            with open("conversation_history.json", "w") as f:
                json.dump({
                    "history": self.history,
                    "context": self.context
                }, f, indent=2)
        except Exception:
            pass

    def load_history(self):
        """Load history from file"""
        try:
            if os.path.exists("conversation_history.json"):
                with open("conversation_history.json", "r") as f:
                    data = json.load(f)
                    self.history = data.get("history", [])[-self.max_history:]
                    self.context = data.get("context", {})
        except Exception:
            pass

    def get_statistics(self) -> Dict:
        """Get usage statistics"""
        total_commands = len(self.history)
        successful = sum(1 for e in self.history if e["result"]["success"])
        failed = total_commands - successful

        return {
            "total_commands": total_commands,
            "successful": successful,
            "failed": failed,
            "success_rate": f"{(successful/total_commands*100):.1f}%" if total_commands > 0 else "0%"
        }

modules/file_management/desktop_sync_man.content:
"""
Desktop Sync Manager - Auto-download batch file and sync desktop files
"""

import os
import sys
import shutil
import json
from pathlib import Path
from datetime import datetime


class DesktopSyncManager:
    """Manages desktop file synchronization and batch file distribution"""

    def __init__(self):
        # Get script directory for finding batch file
        self.script_dir = Path(__file__).parent.absolute()

        # Use actual Windows Desktop
        self.desktop = Path.home() / "Desktop"

        # Config files
        self.sync_config_file = "desktop_sync_config.json"
        self.batch_file_name = "desktop_file_controller.bat"
        self.batch_file = self.script_dir / self.batch_file_name
        self.downloads_ready_file = "downloads_ready.txt"

        # Detect OS
        self.is_windows = sys.platform.startswith('win')

    def prepare_batch_file_download(self):
        """Prepare batch file for local Windows use"""
        try:
            # Check if batch file exists in script directory
            if not self.batch_file.exists():
                # Provide helpful message for Windows users
                current_dir = os.getcwd()
                script_dir = str(self.script_dir)

                return {
                    "success": False,
                    "message": f"Batch file '{self.batch_file_name}' not found!\n" + 
                              f"   Current directory: {current_dir}\n" +
                              f"   Script directory: {script_dir}\n" +
                              f"   Looking for: {self.batch_file}\n\n" +
                              f"   💡 Please download '{self.batch_file_name}' from Replit\n" +
                              f"      and place it in: {script_dir}"
                }

            # Create ready-to-use instructions for local Windows
            instructions = f"""
╔══════════════════════════════════════════════════════════╗
║        DESKTOP FILE CONTROLLER - READY TO USE            ║
╚══════════════════════════════════════════════════════════╝

✅ Batch file found: {self.batch_file.name}
📂 Location: {self.batch_file}
📦 File size: {self.batch_file.stat().st_size} bytes
💻 System: Windows {'✓' if self.is_windows else '(Running on non-Windows OS)'}

🎯 QUICK START:
  1. Double-click '{self.batch_file.name}' to run
  2. Or run from command prompt:
     cd "{self.script_dir}"
     {self.batch_file.name}

📂 Managing your Desktop:
  - Desktop path: {self.desktop}
  - Use the batch file menu to organize files
  - Options 1-13 available for file management

💡 The batch file will manage YOUR real Windows desktop!

Generated: {datetime.now().strftime("%Y-%m-%d %H:%M:%S")}
"""

            with open(self.downloads_ready_file, 'w', encoding='utf-8') as f:
                f.write(instructions)

            return {
                "success": True,
                "message": "Batch file ready to use on Windows",
                "instructions_file": self.downloads_ready_file,
                "batch_file": str(self.batch_file),
                "file_size": self.batch_file.stat().st_size
            }

        except Exception as e:
            return {
                "success": False,
                "message": f"Error preparing batch file: {str(e)}"
            }

    def scan_desktop(self):
        """Scan and analyze desktop files and folders"""
        try:
            if not self.desktop.exists():
                return {
                    "success": False,
                    "message": f"Desktop not found at {self.desktop}"
                }

            scan_data = {
                "scan_time": datetime.now().isoformat(),
                "desktop_path": str(self.desktop),
                "folders": [],
                "files": [],
                "statistics": {
                    "total_folders": 0,
                    "total_files": 0,
                    "total_size_bytes": 0,
                    "file_types": {}
                }
            }

            for item in self.desktop.iterdir():
                item_info = {
                    "name": item.name,
                    "path": str(item),
                    "size": item.stat().st_size if item.is_file() else 0,
                    "modified": datetime.fromtimestamp(item.stat().st_mtime).isoformat()
                }

                if item.is_dir():
                    # Count items in folder
                    try:
                        item_count = len(list(item.iterdir()))
                        item_info["item_count"] = item_count
                    except:
                        item_info["item_count"] = 0
                    scan_data["folders"].append(item_info)
                    scan_data["statistics"]["total_folders"] += 1
                else:
                    # Get file extension
                    ext = item.suffix.lower() if item.suffix else "no_extension"
                    item_info["extension"] = ext
                    scan_data["files"].append(item_info)
                    scan_data["statistics"]["total_files"] += 1
                    scan_data["statistics"]["total_size_bytes"] += item_info["size"]

                    # Track file types
                    if ext in scan_data["statistics"]["file_types"]:
                        scan_data["statistics"]["file_types"][ext] += 1
                    else:
                        scan_data["statistics"]["file_types"][ext] = 1

            return {
                "success": True,
                "data": scan_data
            }

        except Exception as e:
            return {
                "success": False,
                "message": f"Error scanning desktop: {str(e)}"
            }

    def save_desktop_data(self, scan_data):
        """Save scanned desktop data to JSON file"""
        try:
            json_file = self.script_dir / "desktop_data.json"
            with open(json_file, 'w', encoding='utf-8') as f:
                json.dump(scan_data, f, indent=2)

            return {
                "success": True,
                "file": str(json_file),
                "message": "Desktop data saved successfully"
            }
        except Exception as e:
            return {
                "success": False,
                "message": f"Error saving data: {str(e)}"
            }

    def load_desktop_data(self):
        """Load previously saved desktop data"""
        try:
            json_file = self.script_dir / "desktop_data.json"
            if not json_file.exists():
                return {
                    "success": False,
                    "message": "No saved desktop data found"
                }

            with open(json_file, 'r', encoding='utf-8') as f:
                data = json.load(f)

            return {
                "success": True,
                "data": data
            }
        except Exception as e:
            return {
                "success": False,
                "message": f"Error loading data: {str(e)}"
            }

    def display_desktop_summary(self, scan_data):
        """Display a summary of the desktop scan"""
        stats = scan_data["statistics"]

        print("\n" + "="*60)
        print("📊 DESKTOP ANALYSIS SUMMARY")
        print("="*60)
        print(f"📂 Desktop Location: {scan_data['desktop_path']}")
        print(f"📅 Scanned: {datetime.fromisoformat(scan_data['scan_time']).strftime('%Y-%m-%d %H:%M:%S')}")
        print(f"\n📁 Total Folders: {stats['total_folders']}")
        print(f"📄 Total Files: {stats['total_files']}")
        print(f"💾 Total Size: {self.format_size(stats['total_size_bytes'])}")

        if stats["file_types"]:
            print(f"\n📑 File Types Found:")
            for ext, count in sorted(stats["file_types"].items(), key=lambda x: x[1], reverse=True)[:10]:
                ext_display = ext if ext != "no_extension" else "(no extension)"
                print(f"   {ext_display}: {count} file(s)")

        if scan_data["folders"]:
            print(f"\n📂 Folders on Desktop:")
            for folder in scan_data["folders"][:15]:
                print(f"   • {folder['name']} ({folder['item_count']} items)")
            if len(scan_data["folders"]) > 15:
                print(f"   ... and {len(scan_data['folders']) - 15} more folders")

        print("="*60 + "\n")

    def format_size(self, bytes):
        """Format bytes to human readable size"""
        for unit in ['B', 'KB', 'MB', 'GB']:
            if bytes < 1024.0:
                return f"{bytes:.2f} {unit}"
            bytes /= 1024.0
        return f"{bytes:.2f} TB"

    def create_desktop_structure_json(self):
        """Create JSON representation of desktop structure (legacy method)"""
        scan_result = self.scan_desktop()
        if not scan_result["success"]:
            return scan_result

        save_result = self.save_desktop_data(scan_result["data"])

        return {
            "success": True,
            "structure": scan_result["data"],
            "json_file": save_result.get("file", "desktop_data.json"),
            "total_folders": scan_result["data"]["statistics"]["total_folders"],
            "total_files": scan_result["data"]["statistics"]["total_files"]
        }

    def setup_sample_desktop(self):
        """Create sample desktop structure for testing"""
        try:
            # Create desktop if it doesn't exist
            self.desktop.mkdir(parents=True, exist_ok=True)

            # Create sample folders
            sample_folders = [
                "coding",
                "projects", 
                "documents",
                "downloads",
                "work",
                "personal"
            ]

            created = []
            for folder in sample_folders:
                folder_path = self.desktop / folder
                if not folder_path.exists():
                    folder_path.mkdir()
                    created.append(folder)

                    # Add sample files
                    if folder == "coding":
                        (folder_path / "main.py").write_text("# Python code here")
                        (folder_path / "app.js").write_text("// JavaScript code here")
                    elif folder == "documents":
                        (folder_path / "notes.txt").write_text("Sample notes")
                        (folder_path / "report.txt").write_text("Sample report")

            return {
                "success": True,
                "created_folders": created,
                "total_folders": len(sample_folders),
                "desktop_path": str(self.desktop)
            }

        except Exception as e:
            return {
                "success": False,
                "message": f"Error setting up desktop: {str(e)}"
            }

    def auto_startup_sequence(self):
        """Run automatic startup sequence"""
        results = {
            "timestamp": datetime.now().isoformat(),
            "steps": []
        }

        # Step 1: Setup sample desktop (if empty)
        setup_result = self.setup_sample_desktop()
        results["steps"].append({
            "step": "Setup Desktop Structure",
            "status": "success" if setup_result["success"] else "failed",
            "details": setup_result
        })

        # Step 2: Prepare batch file download
        batch_result = self.prepare_batch_file_download()
        results["steps"].append({
            "step": "Prepare Batch File",
            "status": "success" if batch_result["success"] else "failed",
            "details": batch_result
        })

        # Step 3: Create desktop structure JSON
        structure_result = self.create_desktop_structure_json()
        results["steps"].append({
            "step": "Create Desktop Structure",
            "status": "success" if structure_result["success"] else "failed",
            "details": structure_result
        })

        # Overall success
        results["success"] = all(
            step["status"] == "success" for step in results["steps"]
        )

        return results

    def get_download_instructions(self):
        """Get formatted download instructions"""
        if os.path.exists(self.downloads_ready_file):
            with open(self.downloads_ready_file, 'r') as f:
                return f.read()
        return "Download instructions not generated yet. Run auto_startup_sequence() first."


def interactive_startup():
    """Interactive startup - scans desktop and asks user what to do"""
    print("\n" + "="*60)
    print("🚀 DESKTOP FILE & FOLDER AUTOMATOR")
    print("="*60)

    manager = DesktopSyncManager()

    # Step 1: Scan the desktop
    print("\n🔍 Scanning your desktop...")
    scan_result = manager.scan_desktop()

    if not scan_result["success"]:
        print(f"❌ Error: {scan_result['message']}")
        return

    scan_data = scan_result["data"]

    # Step 2: Display summary
    manager.display_desktop_summary(scan_data)

    # Step 3: Save the data
    print("💾 Saving desktop data...")
    save_result = manager.save_desktop_data(scan_data)
    if save_result["success"]:
        print(f"✅ Data saved to: {save_result['file']}\n")

    # Step 4: Ask user what to do
    print("="*60)
    print("📋 WHAT WOULD YOU LIKE TO DO?")
    print("="*60)
    print("1. 📥 Download/Setup batch file controller")
    print("2. 🗂️  View detailed file analysis")
    print("3. 🔄 Re-scan desktop")
    print("4. 🚀 Launch desktop automation (batch file)")
    print("5. 📊 View saved desktop history")
    print("6. ❌ Exit")
    print("="*60)

    try:
        choice = input("\n👉 Enter your choice (1-6): ").strip()

        if choice == "1":
            print("\n🔧 Setting up batch file...")
            batch_result = manager.prepare_batch_file_download()
            if batch_result["success"]:
                print(f"✅ {batch_result['message']}")
                print(f"\n📂 Batch file location: {batch_result['batch_file']}")
                if manager.is_windows:
                    print("\n🚀 You can now run the batch file:")
                    print(f"   Double-click: {manager.batch_file_name}")
                    launch = input("\n🚀 Launch batch file now? (y/n): ").strip().lower()
                    if launch == 'y':
                        os.system(f'start cmd /k "{manager.batch_file}"')
            else:
                print(f"❌ {batch_result['message']}")

        elif choice == "2":
            print("\n📊 DETAILED FILE ANALYSIS")
            print("="*60)
            print(f"Total items: {len(scan_data['files']) + len(scan_data['folders'])}")
            if scan_data['files']:
                print(f"\n📄 Files ({len(scan_data['files'])}):")
                for file in scan_data['files'][:20]:
                    size = manager.format_size(file['size'])
                    print(f"   • {file['name']} ({size}) - {file['extension']}")
                if len(scan_data['files']) > 20:
                    print(f"   ... and {len(scan_data['files']) - 20} more files")

        elif choice == "3":
            print("\n🔄 Re-scanning desktop...")
            interactive_startup()
            return

        elif choice == "4":
            if manager.batch_file.exists():
                print(f"\n🚀 Launching {manager.batch_file_name}...")
                if manager.is_windows:
                    os.system(f'start cmd /k "{manager.batch_file}"')
                else:
                    print("❌ Batch file can only run on Windows")
            else:
                print(f"❌ Batch file not found. Please download it first (option 1)")

        elif choice == "5":
            load_result = manager.load_desktop_data()
            if load_result["success"]:
                print("\n📊 SAVED DESKTOP DATA:")
                manager.display_desktop_summary(load_result["data"])
            else:
                print(f"❌ {load_result['message']}")

        elif choice == "6":
            print("\n👋 Goodbye!")
            return

        else:
            print("\n⚠️  Invalid choice. Please select 1-6.")

    except KeyboardInterrupt:
        print("\n\n👋 Exiting...")
        return
    except Exception as e:
        print(f"\n❌ Error: {str(e)}")

    # Ask if user wants to continue
    print("\n" + "="*60)
    continue_choice = input("📋 Continue with another action? (y/n): ").strip().lower()
    if continue_choice == 'y':
        interactive_startup()
    else:
        print("\n✅ Desktop data has been saved.")
        print(f"💡 Run this script anytime to manage your desktop!")
        print(f"🚀 Or double-click '{manager.batch_file_name}' for quick access\n")


def auto_initialize_on_gui_start():
    """Called automatically when GUI starts (legacy function)"""
    print("\n" + "="*60)
    print("🚀 DESKTOP SYNC MANAGER - AUTO STARTUP")
    print("="*60)

    manager = DesktopSyncManager()
    results = manager.auto_startup_sequence()

    print("\n📊 Startup Sequence Results:")
    print("-"*60)

    for step in results["steps"]:
        status_icon = "✅" if step["status"] == "success" else "❌"
        print(f"{status_icon} {step['step']}: {step['status'].upper()}")

        if "details" in step:
            details = step["details"]
            if step["status"] == "success":
                if "created_folders" in details and details["created_folders"]:
                    print(f"   Created: {', '.join(details['created_folders'])}")
                if "total_folders" in details:
                    print(f"   Total folders: {details['total_folders']}")
                if "batch_file" in details:
                    print(f"   Batch file: {details['batch_file']}")
            else:
                if "message" in details:
                    for line in details["message"].split('\n'):
                        if line.strip():
                            print(f"   {line}")

    print("\n" + "="*60)

    if results["success"]:
        print("✅ ALL SYSTEMS READY!")
        if manager.is_windows:
            print(f"\n🚀 READY TO USE: Double-click '{manager.batch_file_name}'")
            print(f"   Location: {manager.batch_file}")
        else:
            print("\n📥 DOWNLOAD YOUR BATCH FILE:")
            print(f"   Right-click '{manager.batch_file_name}' → Download to Windows PC")
        print("\n📂 Desktop synchronized with test folders")
        print(f"   View: {manager.desktop}")
    else:
        print("⚠️  Some steps had issues. Check details above.")

    print("="*60 + "\n")

    return results


if __name__ == "__main__":
    # Run interactive startup
    interactive_startup()

