modules/automation/gui_automation.py.content:
import time
import os
import platform
from typing import Any

pyautogui: Any = None
pyperclip: Any = None
GUI_AVAILABLE = False

try:
    import pyautogui
    import pyperclip
    GUI_AVAILABLE = True
    pyautogui.FAILSAFE = True
    pyautogui.PAUSE = 0.1
    pyautogui.MINIMUM_DURATION = 0
    pyautogui.MINIMUM_SLEEP = 0
except Exception as e:
    GUI_AVAILABLE = False
    print(f"⚠️  GUI automation not available in this environment: {e}")
    print("Running in DEMO MODE - commands will be simulated")

class GUIAutomation:
    """Handles all GUI automation tasks using PyAutoGUI"""

    def __init__(self):
        self.demo_mode = not GUI_AVAILABLE
        if GUI_AVAILABLE:
            self.screen_width, self.screen_height = pyautogui.size()
            print(f"📺 Screen size detected: {self.screen_width}x{self.screen_height}")
        else:
            self.screen_width, self.screen_height = 1920, 1080
            print(f"📺 Simulated screen size: {self.screen_width}x{self.screen_height}")

        self.system = platform.system()
        self.last_folder_suggestions = []  # Store suggestions for last failed folder operation

    def _log_demo(self, action: str):
        """Log demo mode actions"""
        if self.demo_mode:
            print(f"  [DEMO] {action}")

    def single_click(self, x: int, y: int) -> bool:
        """Simple single click at position"""
        try:
            if self.demo_mode:
                self._log_demo(f"Would click at ({x}, {y})")
                return True

            print(f"  🖱️  Clicking at ({x}, {y})")
            pyautogui.click(x, y)
            return True
        except Exception as e:
            print(f"Error clicking: {e}")
            return False

    def double_click(self, x: int, y: int) -> bool:
        """Perform a double-click at position"""
        try:
            if self.demo_mode:
                self._log_demo(f"Would double click at ({x}, {y})")
                return True

            print(f"  🖱️  Double click at ({x}, {y})")
            pyautogui.moveTo(x, y, duration=0.15)
            time.sleep(0.1)
            pyautogui.click(x, y, clicks=2, interval=0.1)
            return True
        except Exception as e:
            print(f"Error double clicking: {e}")
            return False

    def click_at_position(self, x: int, y: int) -> bool:
        """Single click at a specific position - wrapper for clarity"""
        return self.single_click(x, y)

    def get_relative_position(self, width_percent: float, height_percent: float) -> tuple:
        """Get screen position based on percentage of screen size"""
        x = int(self.screen_width * width_percent / 100)
        y = int(self.screen_height * height_percent / 100)
        return (x, y)

    def focus_browser_address_bar(self) -> bool:
        """Focus the browser's address bar"""
        try:
            if self.demo_mode:
                self._log_demo("Would focus browser address bar")
                return True

            print(f"  🌐 Focusing browser address bar...")
            if self.system == "Darwin":
                pyautogui.hotkey('command', 'l')
            else:
                pyautogui.hotkey('ctrl', 'l')
            time.sleep(0.3)
            return True
        except Exception as e:
            print(f"Error focusing address bar: {e}")
            return False

    def activate_window(self) -> bool:
        """Click on the window to activate/focus it"""
        try:
            if self.demo_mode:
                self._log_demo("Would activate window")
                return True

            center_x = self.screen_width // 2
            center_y = self.screen_height // 2
            pyautogui.click(center_x, center_y)
            time.sleep(0.2)
            return True
        except Exception as e:
            print(f"Error activating window: {e}")
            return False

    def open_application(self, app_name: str) -> bool:
        """Open an application based on the operating system"""
        try:
            if self.demo_mode:
                self._log_demo(f"Would open application: {app_name}")
                return True

            if self.system == "Windows":
                pyautogui.press('win')
                time.sleep(0.5)
                pyautogui.write(app_name, interval=0.1)
                time.sleep(0.5)
                pyautogui.press('enter')
            elif self.system == "Darwin":
                pyautogui.hotkey('command', 'space')
                time.sleep(0.5)
                pyautogui.write(app_name, interval=0.1)
                time.sleep(0.5)
                pyautogui.press('enter')
            elif self.system == "Linux":
                pyautogui.hotkey('alt', 'f2')
                time.sleep(0.5)
                pyautogui.write(app_name, interval=0.1)
                time.sleep(0.5)
                pyautogui.press('enter')
            else:
                return False

            return True
        except Exception as e:
            print(f"Error opening application: {e}")
            return False

    def type_text(self, text: str, interval: float = 0.05) -> bool:
        """Type text with specified interval between keystrokes"""
        try:
            if self.demo_mode:
                self._log_demo(f"Would type: '{text}'")
                return True

            pyautogui.write(text, interval=interval)
            return True
        except Exception as e:
            print(f"Error typing text: {e}")
            return False

    def paste_text(self, text: str) -> bool:
        """Paste text using clipboard"""
        try:
            if self.demo_mode:
                self._log_demo(f"Would paste: '{text[:50]}...'")
                return True

            pyperclip.copy(text)
            time.sleep(0.1)
            if self.system == "Darwin":
                pyautogui.hotkey('command', 'v')
            else:
                pyautogui.hotkey('ctrl', 'v')
            time.sleep(0.1)
            return True
        except Exception as e:
            print(f"Error pasting text: {e}")
            return False

    def click(self, x: int | None = None, y: int | None = None, button: str = 'left', clicks: int = 1) -> bool:
        """Click at specified position or current position"""
        try:
            if self.demo_mode:
                if x is not None and y is not None:
                    self._log_demo(f"Would click {button} button at ({x}, {y})")
                else:
                    self._log_demo(f"Would click {button} button at current position")
                return True

            if x is not None and y is not None:
                if clicks == 1:
                    return self.single_click(x, y)
                else:
                    pyautogui.click(x, y, button=button, clicks=clicks, interval=0.1)
            else:
                pyautogui.click(button=button, clicks=clicks)
            return True
        except Exception as e:
            print(f"Error clicking: {e}")
            return False

    def move_mouse(self, x: int, y: int, duration: float = 0.5) -> bool:
        """Move mouse to specified position"""
        try:
            if self.demo_mode:
                self._log_demo(f"Would move mouse to ({x}, {y})")
                return True

            pyautogui.moveTo(x, y, duration=duration)
            return True
        except Exception as e:
            print(f"Error moving mouse: {e}")
            return False

    def press_key(self, key: str, presses: int = 1) -> bool:
        """Press a keyboard key"""
        try:
            if self.demo_mode:
                self._log_demo(f"Would press key: {key} ({presses} time(s))")
                return True

            pyautogui.press(key, presses=presses, interval=0.1)
            return True
        except Exception as e:
            print(f"Error pressing key: {e}")
            return False

    def hotkey(self, *keys) -> bool:
        """Press a combination of keys"""
        try:
            if self.demo_mode:
                self._log_demo(f"Would press hotkey: {'+'.join(keys)}")
                return True

            pyautogui.hotkey(*keys)
            return True
        except Exception as e:
            print(f"Error with hotkey: {e}")
            return False

    def screenshot(self, filename: str = "screenshot.png"):
        """
        Take a screenshot and save it

        Args:
            filename: Name/path for the screenshot file

        Returns:
            Path to the screenshot file on success, None on failure
        """
        try:
            if self.demo_mode:
                self._log_demo(f"Would take screenshot and save as: {filename}")
                return None

            screenshot = pyautogui.screenshot()
            screenshot.save(filename)
            print(f"Screenshot saved as {filename}")
            return filename
        except Exception as e:
            print(f"Error taking screenshot: {e}")
            return None

    def copy_to_clipboard(self, text: str) -> bool:
        """Copy text to clipboard"""
        try:
            if self.demo_mode:
                self._log_demo(f"Would copy to clipboard: '{text[:50]}...'")
                return True

            pyperclip.copy(text)
            return True
        except Exception as e:
            print(f"Error copying to clipboard: {e}")
            return False

    def paste_from_clipboard(self) -> bool:
        """Paste from clipboard"""
        try:
            if self.demo_mode:
                self._log_demo("Would paste from clipboard")
                return True

            if self.system == "Darwin":
                pyautogui.hotkey('command', 'v')
            else:
                pyautogui.hotkey('ctrl', 'v')
            return True
        except Exception as e:
            print(f"Error pasting: {e}")
            return False

    def get_mouse_position(self) -> tuple:
        """Get current mouse position"""
        if self.demo_mode:
            return (0, 0)
        return pyautogui.position()

    def wait(self, seconds: float) -> bool:
        """Wait for specified seconds"""
        try:
            if self.demo_mode:
                self._log_demo(f"Would wait {seconds} seconds")
                time.sleep(0.1)
                return True

            time.sleep(seconds)
            return True
        except Exception as e:
            print(f"Error waiting: {e}")
            return False

    def get_desktop_path(self) -> str:
        """Get the path to the user's Desktop folder"""
        home = os.path.expanduser("~")

        if self.system == "Windows":
            desktop = os.path.join(home, "Desktop")
        elif self.system == "Darwin":
            desktop = os.path.join(home, "Desktop")
        else:
            desktop_path = os.path.join(home, "Desktop")
            if not os.path.exists(desktop_path):
                desktop = home
            else:
                desktop = desktop_path

        return desktop

    def find_similar_folders(self, folder_name: str, search_path: str, max_suggestions: int = 5):
        """Find folders with similar names using fuzzy matching"""
        try:
            if not os.path.exists(search_path):
                return []

            # Get all folders in the directory
            all_items = os.listdir(search_path)
            folders = [item for item in all_items if os.path.isdir(os.path.join(search_path, item))]

            if not folders:
                return []

            # Normalize search term
            search_lower = folder_name.lower()

            # Calculate similarity scores
            suggestions = []
            for folder in folders:
                folder_lower = folder.lower()
                score = 0

                # Exact match (case-insensitive)
                if folder_lower == search_lower:
                    score = 100
                # Contains the search term
                elif search_lower in folder_lower:
                    score = 80
                # Search term contains folder name
                elif folder_lower in search_lower:
                    score = 70
                # First letters match
                elif folder_lower.startswith(search_lower[:3] if len(search_lower) >= 3 else search_lower[0]):
                    score = 60
                # Contains any word from search
                else:
                    search_words = search_lower.split()
                    folder_words = folder_lower.split()
                    common_words = set(search_words) & set(folder_words)
                    if common_words:
                        score = 50

                if score > 0:
                    suggestions.append((folder, score))

            # Sort by score (highest first) and return top suggestions
            suggestions.sort(key=lambda x: x[1], reverse=True)
            return [folder for folder, score in suggestions[:max_suggestions]]

        except Exception as e:
            print(f"Error finding similar folders: {e}")
            return []

    def open_folder(self, folder_path: str = None, folder_name: str = None) -> bool:
        """
        Open a folder in the file manager

        Args:
            folder_path: Full path to the folder
            folder_name: Name of folder (will search in Desktop, Documents, Downloads, Home)

        Returns:
            True if successful, False otherwise
        """
        try:
            target_path = None
            self.last_folder_suggestions = []  # Clear previous suggestions

            if folder_path:
                target_path = os.path.expanduser(folder_path)
            elif folder_name:
                home = os.path.expanduser("~")
                desktop = self.get_desktop_path()

                search_locations = [
                    desktop,
                    os.path.join(home, "Documents"),
                    os.path.join(home, "Downloads"),
                    home,
                    os.path.join(desktop, folder_name),
                    os.path.join(home, "Documents", folder_name),
                    os.path.join(home, "Downloads", folder_name)
                ]

                for location in search_locations:
                    if os.path.exists(location):
                        if location.endswith(folder_name) or os.path.basename(location) == folder_name:
                            target_path = location
                            break
                        elif os.path.isdir(os.path.join(location, folder_name)):
                            target_path = os.path.join(location, folder_name)
                            break

                if not target_path:
                    # Find suggestions from Desktop first
                    suggestions = self.find_similar_folders(folder_name, desktop)
                    self.last_folder_suggestions = suggestions

                    print(f"⚠️  Folder '{folder_name}' not found in common locations")
                    if suggestions:
                        print(f"   💡 Similar folders on Desktop: {', '.join(suggestions[:3])}")
                    return False
            else:
                target_path = self.get_desktop_path()

            if not os.path.exists(target_path):
                print(f"⚠️  Path does not exist: {target_path}")
                return False

            if self.demo_mode:
                self._log_demo(f"Would open folder: {target_path}")
                return True

            print(f"📂 Opening folder: {target_path}")

            import subprocess
            if self.system == "Windows":
                subprocess.Popen(['explorer', target_path])
            elif self.system == "Darwin":
                subprocess.Popen(['open', target_path])
            else:
                subprocess.Popen(['xdg-open', target_path], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)

            return True

        except Exception as e:
            print(f"Error opening folder: {e}")
            return False

    def open_desktop_folder(self, folder_name: str = None) -> bool:
        """
        Open a folder on the Desktop or the Desktop itself

        Args:
            folder_name: Name of folder on Desktop (None to open Desktop itself)

        Returns:
            True if successful, False otherwise
        """
        try:
            desktop_path = self.get_desktop_path()
            self.last_folder_suggestions = []  # Clear previous suggestions

            if folder_name:
                target_path = os.path.join(desktop_path, folder_name)
                if not os.path.exists(target_path):
                    # Find similar folders to suggest
                    suggestions = self.find_similar_folders(folder_name, desktop_path)
                    self.last_folder_suggestions = suggestions

                    print(f"⚠️  Folder '{folder_name}' not found on Desktop")
                    print(f"   Searched: {target_path}")
                    if suggestions:
                        print(f"   💡 Did you mean: {', '.join(suggestions[:3])}")
                    return False
            else:
                target_path = desktop_path

            if self.demo_mode:
                self._log_demo(f"Would open Desktop folder: {target_path}")
                return True

            print(f"📂 Opening Desktop folder: {target_path}")

            import subprocess
            if self.system == "Windows":
                subprocess.Popen(['explorer', target_path])
            elif self.system == "Darwin":
                subprocess.Popen(['open', target_path])
            else:
                subprocess.Popen(['xdg-open', target_path], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)

            return True

        except Exception as e:
            print(f"Error opening Desktop folder: {e}")
            return False

modules/system/system_control.py.content:
"""
System Control Module
Handles system-level automation: brightness, audio, sleep/wake, disk cleanup
"""

import platform
import subprocess
import os
import shutil
import time
from datetime import datetime, timedelta
import json
import psutil
import threading

class SystemController:
    def __init__(self):
        self.os = platform.system()
        self.config_file = "system_config.json"
        self.shutdown_process = None
        self.batch_files_dir = os.path.join(os.path.dirname(os.path.dirname(os.path.dirname(__file__))), "scripts", "windows_controls")
        self.load_config()

    def load_config(self):
        """Load system configuration"""
        if os.path.exists(self.config_file):
            with open(self.config_file, 'r') as f:
                self.config = json.load(f)
        else:
            self.config = {
                "sleep_schedule": {"enabled": False, "time": "23:00"},
                "wake_schedule": {"enabled": False, "time": "07:00"},
                "auto_cleanup": {"enabled": False, "disk_limit": 90},
                "brightness_schedule": {"enabled": False, "day_brightness": 80, "night_brightness": 30}
            }
            self.save_config()

    def save_config(self):
        """Save system configuration"""
        with open(self.config_file, 'w') as f:
            json.dump(self.config, f, indent=2)

    def mute_microphone(self):
        """Mute system microphone"""
        try:
            if self.os == "Windows":
                from pycaw.pycaw import AudioUtilities, IAudioEndpointVolume
                from comtypes import CLSCTX_ALL

                devices = AudioUtilities.GetMicrophone()
                if devices:
                    interface = devices.Activate(IAudioEndpointVolume._iid_, CLSCTX_ALL, None)
                    volume = interface.QueryInterface(IAudioEndpointVolume)
                    volume.SetMute(True, None)
                    return "✅ Microphone muted"
                else:
                    return "⚠️ No microphone device found"
            elif self.os == "Darwin":
                subprocess.run(["osascript", "-e", "set volume input volume 0"], check=False)
                return "✅ Microphone muted"
            elif self.os == "Linux":
                subprocess.run(["amixer", "set", "Capture", "nocap"], check=False)
                return "✅ Microphone muted"
        except Exception as e:
            return f"❌ Failed to mute microphone: {str(e)}"

    def unmute_microphone(self):
        """Unmute system microphone"""
        try:
            if self.os == "Windows":
                from pycaw.pycaw import AudioUtilities, IAudioEndpointVolume
                from comtypes import CLSCTX_ALL

                devices = AudioUtilities.GetMicrophone()
                if devices:
                    interface = devices.Activate(IAudioEndpointVolume._iid_, CLSCTX_ALL, None)
                    volume = interface.QueryInterface(IAudioEndpointVolume)
                    volume.SetMute(False, None)
                    return "✅ Microphone unmuted"
                else:
                    return "⚠️ No microphone device found"
            elif self.os == "Darwin":
                subprocess.run(["osascript", "-e", "set volume input volume 50"], check=False)
                return "✅ Microphone unmuted"
            elif self.os == "Linux":
                subprocess.run(["amixer", "set", "Capture", "cap"], check=False)
                return "✅ Microphone unmuted"
        except Exception as e:
            return f"❌ Failed to unmute microphone: {str(e)}"

    def set_brightness(self, level):
        """Set screen brightness (0-100)"""
        try:
            level = max(0, min(100, int(level)))

            if self.os == "Windows":
                subprocess.run(f"powershell (Get-WmiObject -Namespace root/WMI -Class WmiMonitorBrightnessMethods).WmiSetBrightness(1,{level})", shell=True, check=False)
                return f"✅ Brightness set to {level}%"
            elif self.os == "Darwin":
                subprocess.run(f"brightness {level/100}", shell=True, check=False)
                return f"✅ Brightness set to {level}%"
            elif self.os == "Linux":
                subprocess.run(f"xrandr --output $(xrandr | grep ' connected' | awk '{{print $1}}') --brightness {level/100}", shell=True, check=False)
                return f"✅ Brightness set to {level}%"
        except Exception as e:
            return f"❌ Failed to set brightness: {str(e)}"

    def increase_brightness(self, amount=10):
        """Increase brightness by specified amount"""
        try:
            current = self.get_brightness()
            if current is not None:
                new_level = min(100, current + amount)
                return self.set_brightness(new_level)
            else:
                # If can't get current, just increase by amount
                return self.set_brightness(50 + amount)
        except Exception as e:
            return f"❌ Failed to increase brightness: {str(e)}"

    def decrease_brightness(self, amount=10):
        """Decrease brightness by specified amount"""
        try:
            current = self.get_brightness()
            if current is not None:
                new_level = max(0, current - amount)
                return self.set_brightness(new_level)
            else:
                # If can't get current, just decrease
                return self.set_brightness(max(0, 50 - amount))
        except Exception as e:
            return f"❌ Failed to decrease brightness: {str(e)}"

    def get_brightness(self):
        """Get current brightness level (0-100)"""
        try:
            if self.os == "Windows":
                result = subprocess.run(
                    "powershell (Get-WmiObject -Namespace root/WMI -Class WmiMonitorBrightness).CurrentBrightness",
                    shell=True, capture_output=True, text=True, check=False
                )
                if result.returncode == 0 and result.stdout.strip():
                    return int(result.stdout.strip())
            elif self.os == "Darwin":
                result = subprocess.run("brightness -l", shell=True, capture_output=True, text=True, check=False)
                if result.returncode == 0 and result.stdout.strip():
                    return int(float(result.stdout.strip()) * 100)
            elif self.os == "Linux":
                result = subprocess.run(
                    "xrandr --verbose | grep -i brightness | head -n 1 | awk '{print $2}'",
                    shell=True, capture_output=True, text=True, check=False
                )
                if result.returncode == 0 and result.stdout.strip():
                    return int(float(result.stdout.strip()) * 100)
            return None
        except:
            return None

    def auto_brightness(self):
        """Auto-adjust brightness based on time of day"""
        try:
            current_hour = datetime.now().hour

            if 6 <= current_hour < 18:
                brightness = self.config["brightness_schedule"]["day_brightness"]
            else:
                brightness = self.config["brightness_schedule"]["night_brightness"]

            return self.set_brightness(brightness)
        except Exception as e:
            return f"❌ Auto-brightness failed: {str(e)}"

    # ==================== VOLUME CONTROL ====================

    def set_volume(self, level):
        """Set system volume (0-100)"""
        try:
            level = max(0, min(100, int(level)))

            if self.os == "Windows":
                from pycaw.pycaw import AudioUtilities, IAudioEndpointVolume
                from comtypes import CLSCTX_ALL
                from ctypes import cast, POINTER

                devices = AudioUtilities.GetSpeakers()
                interface = devices.Activate(IAudioEndpointVolume._iid_, CLSCTX_ALL, None)
                volume = interface.QueryInterface(IAudioEndpointVolume)
                volume.SetMasterVolumeLevelScalar(level / 100.0, None)
                return f"🔊 Volume set to {level}%"
            elif self.os == "Darwin":
                subprocess.run(f"osascript -e 'set volume output volume {level}'", shell=True, check=False)
                return f"🔊 Volume set to {level}%"
            elif self.os == "Linux":
                # Use pactl for PulseAudio (most common)
                subprocess.run(f"pactl set-sink-volume @DEFAULT_SINK@ {level}%", shell=True, check=False)
                return f"🔊 Volume set to {level}%"
        except Exception as e:
            return f"❌ Failed to set volume: {str(e)}"

    def increase_volume(self, amount=10):
        """Increase volume by specified amount"""
        try:
            current = self.get_volume()
            if current is not None:
                new_level = min(100, current + amount)
                return self.set_volume(new_level)
            else:
                # If can't get current, use fallback methods
                if self.os == "Darwin":
                    subprocess.run(f"osascript -e 'set volume output volume (output volume of (get volume settings) + {amount})'", shell=True, check=False)
                    return f"🔊 Volume increased by {amount}%"
                elif self.os == "Linux":
                    subprocess.run(f"pactl set-sink-volume @DEFAULT_SINK@ +{amount}%", shell=True, check=False)
                    return f"🔊 Volume increased by {amount}%"
                else:
                    return f"⚠️ Unable to get current volume. Try setting absolute volume instead."
        except Exception as e:
            return f"❌ Failed to increase volume: {str(e)}"

    def decrease_volume(self, amount=10):
        """Decrease volume by specified amount"""
        try:
            current = self.get_volume()
            if current is not None:
                new_level = max(0, current - amount)
                return self.set_volume(new_level)
            else:
                # If can't get current, use fallback methods
                if self.os == "Darwin":
                    subprocess.run(f"osascript -e 'set volume output volume (output volume of (get volume settings) - {amount})'", shell=True, check=False)
                    return f"🔉 Volume decreased by {amount}%"
                elif self.os == "Linux":
                    subprocess.run(f"pactl set-sink-volume @DEFAULT_SINK@ -{amount}%", shell=True, check=False)
                    return f"🔉 Volume decreased by {amount}%"
                else:
                    return f"⚠️ Unable to get current volume. Try setting absolute volume instead."
        except Exception as e:
            return f"❌ Failed to decrease volume: {str(e)}"

    def get_volume(self):
        """Get current volume level (0-100)"""
        try:
            if self.os == "Windows":
                from pycaw.pycaw import AudioUtilities, IAudioEndpointVolume
                from comtypes import CLSCTX_ALL

                devices = AudioUtilities.GetSpeakers()
                interface = devices.Activate(IAudioEndpointVolume._iid_, CLSCTX_ALL, None)
                volume = interface.QueryInterface(IAudioEndpointVolume)
                current_volume = volume.GetMasterVolumeLevelScalar()
                return int(current_volume * 100)
            elif self.os == "Darwin":
                result = subprocess.run(
                    "osascript -e 'output volume of (get volume settings)'",
                    shell=True, capture_output=True, text=True, check=False
                )
                if result.returncode == 0 and result.stdout.strip():
                    return int(result.stdout.strip())
            elif self.os == "Linux":
                result = subprocess.run(
                    "pactl get-sink-volume @DEFAULT_SINK@ | grep -Po '[0-9]+(?=%)' | head -1",
                    shell=True, capture_output=True, text=True, check=False
                )
                if result.returncode == 0 and result.stdout.strip():
                    return int(result.stdout.strip())
            return None
        except:
            return None

    def mute_volume(self):
        """Mute system volume"""
        try:
            if self.os == "Windows":
                from pycaw.pycaw import AudioUtilities, IAudioEndpointVolume
                from comtypes import CLSCTX_ALL

                devices = AudioUtilities.GetSpeakers()
                interface = devices.Activate(IAudioEndpointVolume._iid_, CLSCTX_ALL, None)
                volume = interface.QueryInterface(IAudioEndpointVolume)
                volume.SetMute(True, None)
                return "🔇 Volume muted"
            elif self.os == "Darwin":
                subprocess.run("osascript -e 'set volume output muted true'", shell=True, check=False)
                return "🔇 Volume muted"
            elif self.os == "Linux":
                subprocess.run("pactl set-sink-mute @DEFAULT_SINK@ 1", shell=True, check=False)
                return "🔇 Volume muted"
        except Exception as e:
            return f"❌ Failed to mute volume: {str(e)}"

    def unmute_volume(self):
        """Unmute system volume"""
        try:
            if self.os == "Windows":
                from pycaw.pycaw import AudioUtilities, IAudioEndpointVolume
                from comtypes import CLSCTX_ALL

                devices = AudioUtilities.GetSpeakers()
                interface = devices.Activate(IAudioEndpointVolume._iid_, CLSCTX_ALL, None)
                volume = interface.QueryInterface(IAudioEndpointVolume)
                volume.SetMute(False, None)
                return "🔊 Volume unmuted"
            elif self.os == "Darwin":
                subprocess.run("osascript -e 'set volume output muted false'", shell=True, check=False)
                return "🔊 Volume unmuted"
            elif self.os == "Linux":
                subprocess.run("pactl set-sink-mute @DEFAULT_SINK@ 0", shell=True, check=False)
                return "🔊 Volume unmuted"
        except Exception as e:
            return f"❌ Failed to unmute volume: {str(e)}"

    def toggle_mute(self):
        """Toggle mute/unmute"""
        try:
            if self.os == "Windows":
                from pycaw.pycaw import AudioUtilities, IAudioEndpointVolume
                from comtypes import CLSCTX_ALL

                devices = AudioUtilities.GetSpeakers()
                interface = devices.Activate(IAudioEndpointVolume._iid_, CLSCTX_ALL, None)
                volume = interface.QueryInterface(IAudioEndpointVolume)
                current_mute = volume.GetMute()
                volume.SetMute(not current_mute, None)
                return "🔇 Volume muted" if not current_mute else "🔊 Volume unmuted"
            elif self.os == "Darwin":
                result = subprocess.run(
                    "osascript -e 'output muted of (get volume settings)'",
                    shell=True, capture_output=True, text=True, check=False
                )
                is_muted = result.stdout.strip() == "true"
                if is_muted:
                    return self.unmute_volume()
                else:
                    return self.mute_volume()
            elif self.os == "Linux":
                subprocess.run("pactl set-sink-mute @DEFAULT_SINK@ toggle", shell=True, check=False)
                return "🔊 Volume toggled"
        except Exception as e:
            return f"❌ Failed to toggle mute: {str(e)}"

    def get_volume_info(self):
        """Get detailed volume information"""
        try:
            level = self.get_volume()
            if level is not None:
                return f"🔊 Current Volume: {level}%"
            else:
                return "ℹ️ Unable to retrieve volume level"
        except Exception as e:
            return f"❌ Failed to get volume info: {str(e)}"

    def schedule_sleep(self, time_str="23:00"):
        """
        Schedule PC to enter sleep mode at specific time (NOT shutdown)

        LIMITATIONS:
        - Cannot be cancelled once scheduled
        - Avoid scheduling multiple sleep times
        - For critical scheduling, use OS task scheduler instead
        - Basic timer-based sleep for convenience
        """
        try:
            hours, minutes = map(int, time_str.split(':'))
            now = datetime.now()
            sleep_time = now.replace(hour=hours, minute=minutes, second=0)

            if sleep_time < now:
                sleep_time += timedelta(days=1)

            seconds_until_sleep = (sleep_time - now).total_seconds()

            def execute_sleep():
                """Execute sleep mode after delay"""
                try:
                    time.sleep(seconds_until_sleep)
                    result = self.sleep_mode()
                    self._show_notification(
                        "💤 VATSAL Sleep Mode",
                        f"Entering sleep mode as scheduled at {time_str}"
                    )
                    print(f"[SCHEDULED SLEEP] {result}")
                except Exception as e:
                    error_msg = f"Scheduled sleep failed: {str(e)}"
                    self._show_notification("❌ Sleep Error", error_msg)
                    print(f"[ERROR] {error_msg}")

            threading.Thread(target=execute_sleep, daemon=True).start()
            return f"😴 Sleep mode scheduled for {time_str} ({sleep_time.strftime('%Y-%m-%d %H:%M')})\n⚠️  System will SLEEP (not shutdown) at scheduled time\nℹ️  Cannot be cancelled once set"
        except Exception as e:
            return f"❌ Failed to schedule sleep: {str(e)}"

    def cancel_sleep(self):
        """
        Cancel scheduled sleep

        Note: This only works for shutdown-based scheduling.
        Timer-based sleep schedules cannot be cancelled once started.
        """
        try:
            if self.os == "Windows":
                subprocess.run("shutdown /a", shell=True, check=False)
                return "✅ Shutdown/restart cancelled (if any were scheduled)\nℹ️  Note: Timer-based sleep schedules cannot be cancelled"
            elif self.os in ["Darwin", "Linux"]:
                subprocess.run("sudo shutdown -c", shell=True, check=False)
                return "✅ Shutdown/restart cancelled (if any were scheduled)\nℹ️  Note: Timer-based sleep schedules cannot be cancelled"
        except Exception as e:
            return f"❌ Failed to cancel: {str(e)}"

    def schedule_wake(self, time_str="07:00"):
        """Schedule PC to wake at specific time (Windows only)"""
        try:
            if self.os == "Windows":
                hours, minutes = map(int, time_str.split(':'))
                subprocess.run(f'powershell "powercfg /waketimers /create /type wakeup /time {hours}:{minutes}"', shell=True, check=False)
                return f"✅ Wake scheduled for {time_str}"
            else:
                return "ℹ️ Wake scheduling is only supported on Windows"
        except Exception as e:
            return f"❌ Failed to schedule wake: {str(e)}"

    def clear_temp_files(self):
        """Clear temporary files and cache"""
        try:
            cleared_size = 0
            cleared_files = 0

            temp_dirs = []
            if self.os == "Windows":
                user_profile = os.environ.get('USERPROFILE')
                temp_dirs = [
                    os.environ.get('TEMP'),
                    os.environ.get('TMP'),
                ]
                if user_profile:
                    temp_dirs.append(os.path.join(user_profile, 'AppData', 'Local', 'Temp'))
            elif self.os in ["Darwin", "Linux"]:
                temp_dirs = ['/tmp', os.path.expanduser('~/.cache')]

            for temp_dir in temp_dirs:
                if temp_dir and os.path.exists(temp_dir):
                    for item in os.listdir(temp_dir):
                        item_path = os.path.join(temp_dir, item)
                        try:
                            if os.path.isfile(item_path):
                                size = os.path.getsize(item_path)
                                os.remove(item_path)
                                cleared_size += size
                                cleared_files += 1
                            elif os.path.isdir(item_path):
                                size = sum(os.path.getsize(os.path.join(dirpath, filename))
                                          for dirpath, _, filenames in os.walk(item_path)
                                          for filename in filenames)
                                shutil.rmtree(item_path)
                                cleared_size += size
                                cleared_files += 1
                        except:
                            continue

            cleared_mb = cleared_size / (1024 * 1024)
            return f"✅ Cleared {cleared_files} items ({cleared_mb:.2f} MB)"
        except Exception as e:
            return f"❌ Failed to clear temp files: {str(e)}"

    def empty_recycle_bin(self):
        """Empty recycle bin"""
        try:
            if self.os == "Windows":
                try:
                    import winshell
                    winshell.recycle_bin().empty(confirm=False, show_progress=False, sound=False)
                    return "✅ Recycle bin emptied"
                except (ImportError, Exception):
                    subprocess.run("rd /s /q %temp%", shell=True, check=False)
                    return "✅ Temp cleaned (winshell not available)"
            elif self.os == "Darwin":
                subprocess.run("rm -rf ~/.Trash/*", shell=True, check=False)
                return "✅ Trash emptied"
            elif self.os == "Linux":
                subprocess.run("rm -rf ~/.local/share/Trash/*", shell=True, check=False)
                return "✅ Trash emptied"
        except Exception as e:
            return f"❌ Failed to empty recycle bin: {str(e)}"

    def check_disk_space(self):
        """Check disk space and auto-cleanup if needed"""
        try:
            usage = shutil.disk_usage("/")
            percent_used = (usage.used / usage.total) * 100

            result = f"💾 Disk Usage: {percent_used:.1f}% ({usage.used//(1024**3)}GB / {usage.total//(1024**3)}GB)\n"

            if self.config["auto_cleanup"]["enabled"] and percent_used > self.config["auto_cleanup"]["disk_limit"]:
                result += "\n⚠️ Disk space limit exceeded. Running auto-cleanup...\n"
                cleanup_msg = self.clear_temp_files()
                if cleanup_msg:
                    result += cleanup_msg + "\n"
                bin_msg = self.empty_recycle_bin()
                if bin_msg:
                    result += bin_msg

            return result
        except Exception as e:
            return f"❌ Failed to check disk space: {str(e)}"

