modules/automation/hand_gesture_controll.content:
"""
Hand Gesture Mouse Controller
Control your mouse using hand gestures via webcam
"""

import time
import numpy as np
from typing import Dict, List, Optional, Tuple, Any

try:
    import cv2
    CV2_AVAILABLE = True
except ImportError:
    CV2_AVAILABLE = False
    cv2 = None

try:
    import mediapipe as mp
    MEDIAPIPE_AVAILABLE = True
except ImportError:
    MEDIAPIPE_AVAILABLE = False
    mp = None

try:
    import pyautogui
    PYAUTOGUI_AVAILABLE = True
except ImportError:
    PYAUTOGUI_AVAILABLE = False
    pyautogui = None


class HandGestureController:
    """Control mouse and system with hand gestures using webcam"""

    def __init__(self):
        self.cv2_available = CV2_AVAILABLE
        self.mediapipe_available = MEDIAPIPE_AVAILABLE
        self.pyautogui_available = PYAUTOGUI_AVAILABLE

        self.cap = None
        self.hands = None
        self.mp_hands = None
        self.mp_drawing = None

        self.running = False
        self.screen_width = 1920
        self.screen_height = 1080

        self.prev_x = 0
        self.prev_y = 0
        self.smoothing = 5

        self.click_cooldown = 0
        self.cooldown_frames = 10

        self.gesture_mode = "cursor"

        self.stats = {
            "total_gestures": 0,
            "clicks": 0,
            "scrolls": 0,
            "drags": 0
        }

    def check_dependencies(self) -> Dict[str, bool]:
        """Check which dependencies are available"""
        return {
            'opencv': self.cv2_available,
            'mediapipe': self.mediapipe_available,
            'pyautogui': self.pyautogui_available
        }

    def get_missing_dependencies_message(self) -> str:
        """Get helpful message about missing dependencies"""
        deps = self.check_dependencies()
        missing = [name for name, available in deps.items() if not available]

        if not missing:
            return ""

        install_commands = {
            'opencv': 'pip install opencv-python',
            'mediapipe': 'pip install mediapipe',
            'pyautogui': 'pip install pyautogui'
        }

        msg = f"Missing required dependencies: {', '.join(missing)}\n"
        msg += "Install all with:\n"
        msg += "  pip install opencv-python mediapipe pyautogui numpy\n"

        return msg

    def initialize(self, camera_id: int = 0, detection_confidence: float = 0.7, 
                   tracking_confidence: float = 0.7) -> Dict:
        """Initialize the hand gesture controller"""
        if not all([self.cv2_available, self.mediapipe_available, self.pyautogui_available]):
            return {
                "success": False,
                "error": "Missing dependencies",
                "help": self.get_missing_dependencies_message()
            }

        try:
            self.mp_hands = mp.solutions.hands
            self.mp_drawing = mp.solutions.drawing_utils

            self.hands = self.mp_hands.Hands(
                static_image_mode=False,
                max_num_hands=1,
                model_complexity=1,
                min_detection_confidence=detection_confidence,
                min_tracking_confidence=tracking_confidence
            )

            self.cap = cv2.VideoCapture(camera_id)
            self.cap.set(cv2.CAP_PROP_FRAME_WIDTH, 640)
            self.cap.set(cv2.CAP_PROP_FRAME_HEIGHT, 480)

            if not self.cap.isOpened():
                return {
                    "success": False,
                    "error": "Cannot access webcam",
                    "help": "Make sure your webcam is connected and not in use by another application"
                }

            self.screen_width, self.screen_height = pyautogui.size()

            pyautogui.FAILSAFE = False

            return {
                "success": True,
                "message": "Hand gesture controller initialized",
                "screen_size": f"{self.screen_width}x{self.screen_height}",
                "camera": f"Camera {camera_id} opened successfully"
            }

        except Exception as e:
            return {
                "success": False,
                "error": f"Initialization failed: {str(e)}"
            }

    def count_fingers(self, hand_landmarks) -> int:
        """Count how many fingers are extended"""
        if not hand_landmarks:
            return 0

        fingers = []
        landmarks = hand_landmarks.landmark

        if landmarks[4].x < landmarks[3].x:
            fingers.append(1)
        else:
            fingers.append(0)

        finger_tips = [8, 12, 16, 20]
        finger_pips = [6, 10, 14, 18]

        for tip, pip in zip(finger_tips, finger_pips):
            if landmarks[tip].y < landmarks[pip].y:
                fingers.append(1)
            else:
                fingers.append(0)

        return sum(fingers)

    def get_finger_status(self, hand_landmarks) -> List[int]:
        """Get status of each finger (0=down, 1=up)"""
        if not hand_landmarks:
            return [0, 0, 0, 0, 0]

        fingers = []
        landmarks = hand_landmarks.landmark

        if landmarks[4].x < landmarks[3].x:
            fingers.append(1)
        else:
            fingers.append(0)

        finger_tips = [8, 12, 16, 20]
        finger_pips = [6, 10, 14, 18]

        for tip, pip in zip(finger_tips, finger_pips):
            if landmarks[tip].y < landmarks[pip].y:
                fingers.append(1)
            else:
                fingers.append(0)

        return fingers

    def calculate_distance(self, point1, point2) -> float:
        """Calculate distance between two landmarks"""
        return np.sqrt((point1.x - point2.x)**2 + (point1.y - point2.y)**2 + (point1.z - point2.z)**2)

    def process_cursor_gesture(self, hand_landmarks, frame) -> str:
        """Process cursor movement gestures"""
        landmarks = hand_landmarks.landmark
        index_tip = landmarks[8]
        thumb_tip = landmarks[4]

        frame_height, frame_width, _ = frame.shape

        index_x = int(index_tip.x * frame_width)
        index_y = int(index_tip.y * frame_height)

        screen_x = np.interp(index_x, [100, frame_width - 100], [0, self.screen_width])
        screen_y = np.interp(index_y, [100, frame_height - 100], [0, self.screen_height])

        cursor_x = self.prev_x + (screen_x - self.prev_x) / self.smoothing
        cursor_y = self.prev_y + (screen_y - self.prev_y) / self.smoothing
        self.prev_x, self.prev_y = cursor_x, cursor_y

        pyautogui.moveTo(cursor_x, cursor_y)

        distance = self.calculate_distance(index_tip, thumb_tip)

        if distance < 0.05 and self.click_cooldown == 0:
            pyautogui.click()
            self.click_cooldown = self.cooldown_frames
            self.stats["clicks"] += 1
            return "Click"

        if self.click_cooldown > 0:
            self.click_cooldown -= 1

        return "Moving"

    def process_scroll_gesture(self, hand_landmarks, prev_y_pos) -> Tuple[str, float]:
        """Process scroll gestures"""
        landmarks = hand_landmarks.landmark
        index_tip = landmarks[8]

        current_y = index_tip.y

        if prev_y_pos is not None:
            diff = prev_y_pos - current_y

            if abs(diff) > 0.02:
                scroll_amount = int(diff * 300)
                pyautogui.scroll(scroll_amount)
                self.stats["scrolls"] += 1
                return f"Scroll {'Up' if scroll_amount > 0 else 'Down'}", current_y

        return "Scroll Mode", current_y

    def process_volume_gesture(self, hand_landmarks) -> str:
        """Process volume control gestures"""
        landmarks = hand_landmarks.landmark
        thumb_tip = landmarks[4]
        index_tip = landmarks[8]

        distance = self.calculate_distance(thumb_tip, index_tip)

        volume_level = int(np.interp(distance, [0.02, 0.2], [0, 100]))

        try:
            from ctypes import cast, POINTER
            from comtypes import CLSCTX_ALL
            from pycaw.pycaw import AudioUtilities, IAudioEndpointVolume

            devices = AudioUtilities.GetSpeakers()
            interface = devices.Activate(IAudioEndpointVolume._iid_, CLSCTX_ALL, None)
            volume = cast(interface, POINTER(IAudioEndpointVolume))

            vol_db = np.interp(volume_level, [0, 100], [-65, 0])
            volume.SetMasterVolumeLevel(vol_db, None)

            return f"Volume: {volume_level}%"
        except:
            return "Volume Control (pycaw not installed)"

    def recognize_gesture(self, fingers: List[int]) -> str:
        """Recognize specific gestures based on finger positions"""
        if fingers == [0, 1, 0, 0, 0]:
            return "cursor"
        elif fingers == [0, 1, 1, 0, 0]:
            return "cursor"
        elif fingers == [1, 1, 1, 1, 1]:
            return "scroll"
        elif fingers == [1, 1, 0, 0, 0]:
            return "volume"
        elif fingers == [0, 0, 0, 0, 0]:
            return "drag"
        elif fingers == [0, 0, 0, 0, 1]:
            return "right_click"
        else:
            return "cursor"

    def start(self, show_video: bool = True) -> Dict:
        """Start the hand gesture controller"""
        if not self.hands or not self.cap:
            init_result = self.initialize()
            if not init_result["success"]:
                return init_result

        self.running = True
        prev_scroll_y = None

        print("=" * 60)
        print("HAND GESTURE MOUSE CONTROLLER")
        print("=" * 60)
        print("\n✋ Gestures:")
        print("  • Index finger up           → Move cursor")
        print("  • Index + Middle up         → Move cursor")
        print("  • Pinch (Index + Thumb)     → Left click")
        print("  • All fingers up            → Scroll mode")
        print("  • Thumb + Index up          → Volume control")
        print("  • Closed fist               → Drag mode")
        print("  • Pinky finger only         → Right click")
        print("\n⌨️  Controls:")
        print("  • Press 'q' to quit")
        print("  • Press 's' to toggle stats")
        print("=" * 60)

        show_stats = False

        try:
            while self.running:
                success, frame = self.cap.read()
                if not success:
                    break

                frame = cv2.flip(frame, 1)
                frame_rgb = cv2.cvtColor(frame, cv2.COLOR_BGR2RGB)

                results = self.hands.process(frame_rgb)

                gesture_text = "No Hand Detected"

                if results.multi_hand_landmarks:
                    for hand_landmarks in results.multi_hand_landmarks:
                        if show_video:
                            self.mp_drawing.draw_landmarks(
                                frame,
                                hand_landmarks,
                                self.mp_hands.HAND_CONNECTIONS
                            )

                        fingers = self.get_finger_status(hand_landmarks)
                        gesture_mode = self.recognize_gesture(fingers)

                        if gesture_mode == "cursor":
                            gesture_text = self.process_cursor_gesture(hand_landmarks, frame)
                        elif gesture_mode == "scroll":
                            gesture_text, prev_scroll_y = self.process_scroll_gesture(hand_landmarks, prev_scroll_y)
                        elif gesture_mode == "volume":
                            gesture_text = self.process_volume_gesture(hand_landmarks)
                        elif gesture_mode == "drag":
                            pyautogui.mouseDown()
                            gesture_text = "Dragging"
                            self.stats["drags"] += 1
                        elif gesture_mode == "right_click":
                            if self.click_cooldown == 0:
                                pyautogui.rightClick()
                                self.click_cooldown = self.cooldown_frames
                                self.stats["clicks"] += 1
                            gesture_text = "Right Click"

                        self.stats["total_gestures"] += 1
                else:
                    pyautogui.mouseUp()

                if show_video:
                    cv2.putText(frame, gesture_text, (10, 50),
                               cv2.FONT_HERSHEY_SIMPLEX, 1, (0, 255, 0), 2)

                    cv2.putText(frame, f"Mode: {gesture_mode.upper()}", (10, 90),
                               cv2.FONT_HERSHEY_SIMPLEX, 0.7, (255, 255, 0), 2)

                    if show_stats:
                        y_offset = 130
                        for key, value in self.stats.items():
                            cv2.putText(frame, f"{key}: {value}", (10, y_offset),
                                       cv2.FONT_HERSHEY_SIMPLEX, 0.5, (255, 255, 255), 1)
                            y_offset += 25

                    cv2.imshow('Hand Gesture Controller', frame)

                key = cv2.waitKey(1) & 0xFF
                if key == ord('q'):
                    break
                elif key == ord('s'):
                    show_stats = not show_stats

            return {
                "success": True,
                "message": "Hand gesture controller stopped",
                "stats": self.stats
            }

        except Exception as e:
            return {
                "success": False,
                "error": f"Runtime error: {str(e)}"
            }
        finally:
            self.cleanup()

    def cleanup(self):
        """Clean up resources"""
        self.running = False

        if self.cap:
            self.cap.release()

        if CV2_AVAILABLE:
            cv2.destroyAllWindows()

        if self.hands:
            self.hands.close()

    def get_stats(self) -> Dict:
        """Get gesture statistics"""
        return self.stats.copy()


if __name__ == "__main__":
    controller = HandGestureController()

    deps = controller.check_dependencies()
    print("\n📦 Dependency Check:")
    for dep, available in deps.items():
        status = "✓" if available else "✗"
        print(f"  {status} {dep}")

    if not all(deps.values()):
        print("\n" + controller.get_missing_dependencies_message())
    else:
        print("\n✅ All dependencies available!")
        print("\nStarting hand gesture controller...")
        result = controller.start(show_video=True)
        print(f"\n{result}")

modules/automation/batch_form_filler.py.content:
"""
Batch Form Filler Module
Automatically fills web forms, desktop forms, and applications using templates
"""

import json
import time
import os
from pathlib import Path
from typing import Dict, List, Optional, Any

try:
    import pandas as pd
    PANDAS_AVAILABLE = True
except ImportError:
    PANDAS_AVAILABLE = False
    pd = None

try:
    import pyautogui
    PYAUTOGUI_AVAILABLE = True
except ImportError:
    PYAUTOGUI_AVAILABLE = False
    pyautogui = None

try:
    import pyperclip
    PYPERCLIP_AVAILABLE = True
except ImportError:
    PYPERCLIP_AVAILABLE = False
    pyperclip = None

try:
    from selenium import webdriver
    from selenium.webdriver.common.by import By
    from selenium.webdriver.support.ui import WebDriverWait
    from selenium.webdriver.support import expected_conditions as EC
    from selenium.webdriver.common.keys import Keys
    from selenium.common.exceptions import TimeoutException, NoSuchElementException
    from selenium.webdriver.chrome.options import Options as ChromeOptions
    SELENIUM_AVAILABLE = True
except ImportError:
    SELENIUM_AVAILABLE = False
    webdriver = None


class BatchFormFiller:
    """Intelligent batch form filling with multiple strategies"""

    def __init__(self):
        self.templates_file = "form_templates.json"
        self.templates = self.load_templates()
        self.driver = None
        self.fill_history = []
        self.field_mappings = self.get_field_mappings()
        self.selenium_available = SELENIUM_AVAILABLE
        self.pyautogui_available = PYAUTOGUI_AVAILABLE
        self.pandas_available = PANDAS_AVAILABLE
        self.pyperclip_available = PYPERCLIP_AVAILABLE

    def load_templates(self) -> Dict:
        """Load form templates from JSON"""
        if os.path.exists(self.templates_file):
            with open(self.templates_file, 'r') as f:
                return json.load(f)
        return {}

    def save_templates(self):
        """Save form templates to JSON"""
        with open(self.templates_file, 'w') as f:
            json.dump(self.templates, f, indent=2)

    def get_field_mappings(self) -> Dict[str, List[str]]:
        """Common field name variations for intelligent matching"""
        return {
            'email': ['email', 'e-mail', 'mail', 'email_address', 'user_email', 'contact_email'],
            'first_name': ['first_name', 'firstname', 'fname', 'given_name', 'forename'],
            'last_name': ['last_name', 'lastname', 'lname', 'surname', 'family_name'],
            'full_name': ['full_name', 'name', 'fullname', 'your_name', 'user_name'],
            'phone': ['phone', 'telephone', 'mobile', 'cell', 'phone_number', 'contact_number'],
            'address': ['address', 'street', 'address_line1', 'street_address', 'address1'],
            'city': ['city', 'town', 'locality'],
            'state': ['state', 'province', 'region', 'county'],
            'zip': ['zip', 'zipcode', 'postal', 'postcode', 'postal_code', 'zip_code'],
            'country': ['country', 'nation', 'country_code'],
            'company': ['company', 'organization', 'employer', 'company_name'],
            'job_title': ['job_title', 'title', 'position', 'role'],
            'message': ['message', 'comments', 'feedback', 'description', 'details', 'notes'],
            'subject': ['subject', 'topic', 'regarding'],
            'username': ['username', 'user', 'login', 'account_name'],
            'password': ['password', 'pass', 'pwd'],
            'date_of_birth': ['date_of_birth', 'dob', 'birthdate', 'birth_date', 'birthday']
        }

    def find_field_value(self, field_name: str, template_data: Dict) -> Optional[str]:
        """Intelligently find the value for a field using fuzzy matching"""
        field_lower = field_name.lower().replace('-', '_').replace(' ', '_')

        # Direct match
        if field_lower in template_data:
            return str(template_data[field_lower])

        # Check field mappings
        for key, variations in self.field_mappings.items():
            if field_lower in variations and key in template_data:
                return str(template_data[key])

        # Partial match
        for key in template_data:
            if field_lower in key.lower() or key.lower() in field_lower:
                return str(template_data[key])

        return None

    def check_dependencies(self) -> Dict[str, bool]:
        """Check which dependencies are available"""
        return {
            'selenium': self.selenium_available,
            'pyautogui': self.pyautogui_available,
            'pandas': self.pandas_available,
            'pyperclip': self.pyperclip_available
        }

    def get_missing_dependencies_message(self, required: List[str]) -> str:
        """Get helpful message about missing dependencies"""
        missing = [dep for dep in required if not getattr(self, f'{dep}_available', False)]
        if not missing:
            return ""

        install_commands = {
            'selenium': 'pip install selenium',
            'pyautogui': 'pip install pyautogui',
            'pandas': 'pip install pandas openpyxl',
            'pyperclip': 'pip install pyperclip'
        }

        msg = f"Missing required dependencies: {', '.join(missing)}\n"
        msg += "Install with:\n"
        for dep in missing:
            msg += f"  {install_commands.get(dep, f'pip install {dep}')}\n"

        if 'selenium' in missing:
            msg += "\nNote: Selenium also requires ChromeDriver or another WebDriver.\n"
            msg += "For Replit, consider using desktop or clipboard mode instead.\n"

        return msg

    def _init_webdriver(self) -> Optional[Any]:
        """Initialize WebDriver with proper error handling"""
        if not SELENIUM_AVAILABLE:
            return None

        try:
            options = ChromeOptions()
            options.add_argument('--no-sandbox')
            options.add_argument('--disable-dev-shm-usage')
            options.add_argument('--headless')

            try:
                driver = webdriver.Chrome(options=options)
                return driver
            except Exception as e:
                print(f"ChromeDriver not available: {e}")
                print("Attempting to use Firefox...")
                try:
                    driver = webdriver.Firefox()
                    return driver
                except Exception:
                    return None
        except Exception:
            return None

    def fill_web_form_selenium(self, url: str, template_name: str, submit: bool = False) -> Dict:
        """Fill web form using Selenium with intelligent field detection"""
        if not self.selenium_available:
            return {
                "success": False,
                "error": "Selenium not available",
                "help": self.get_missing_dependencies_message(['selenium'])
            }

        if template_name not in self.templates:
            return {"success": False, "error": f"Template '{template_name}' not found"}

        template_data = self.templates[template_name]

        try:
            # Initialize Selenium
            if not self.driver:
                self.driver = self._init_webdriver()
                if not self.driver:
                    return {
                        "success": False,
                        "error": "WebDriver initialization failed",
                        "help": "ChromeDriver or other WebDriver not configured.\nConsider using desktop_form_pyautogui() or fill_form_clipboard() instead."
                    }

            self.driver.get(url)
            time.sleep(2)

            filled_fields = []
            errors = []

            # Find all input fields
            input_elements = self.driver.find_elements(By.TAG_NAME, 'input')
            textarea_elements = self.driver.find_elements(By.TAG_NAME, 'textarea')
            select_elements = self.driver.find_elements(By.TAG_NAME, 'select')

            all_fields = input_elements + textarea_elements + select_elements

            for element in all_fields:
                field_name = "unknown"
                try:
                    # Get field identifiers
                    field_name = element.get_attribute('name') or element.get_attribute('id') or element.get_attribute('placeholder') or "unknown"
                    field_type = element.get_attribute('type')

                    if not field_name or field_name == "unknown":
                        continue

                    # Skip hidden and submit buttons
                    if field_type in ['hidden', 'submit', 'button']:
                        continue

                    # Find matching value
                    value = self.find_field_value(field_name, template_data)

                    if value:
                        # Handle different field types
                        if element.tag_name == 'select':
                            # Select dropdown
                            from selenium.webdriver.support.ui import Select
                            select = Select(element)
                            try:
                                select.select_by_visible_text(value)
                            except:
                                select.select_by_value(value)
                        elif field_type == 'checkbox':
                            if value.lower() in ['true', 'yes', '1']:
                                if not element.is_selected():
                                    element.click()
                        elif field_type == 'radio':
                            if element.get_attribute('value') == value:
                                element.click()
                        else:
                            # Text input
                            element.clear()
                            element.send_keys(value)

                        filled_fields.append(field_name)

                except Exception as e:
                    errors.append(f"Error filling {field_name}: {str(e)}")

            # Submit if requested
            if submit:
                try:
                    submit_button = self.driver.find_element(By.CSS_SELECTOR, 'button[type="submit"], input[type="submit"]')
                    submit_button.click()
                    time.sleep(2)
                except:
                    errors.append("Could not find or click submit button")

            result = {
                "success": True,
                "filled_fields": filled_fields,
                "total_fields": len(filled_fields),
                "errors": errors,
                "template_used": template_name,
                "url": url
            }

            self.fill_history.append(result)
            return result

        except Exception as e:
            return {"success": False, "error": str(e)}

    def fill_desktop_form_pyautogui(self, template_name: str, delay: float = 0.5) -> Dict:
        """Fill desktop form using PyAutoGUI with tab navigation"""
        if not self.pyautogui_available:
            return {
                "success": False,
                "error": "PyAutoGUI not available",
                "help": self.get_missing_dependencies_message(['pyautogui'])
            }

        if template_name not in self.templates:
            return {"success": False, "error": f"Template '{template_name}' not found"}

        template_data = self.templates[template_name]

        try:
            print(f"Starting form fill in 3 seconds. Click on the first field...")
            time.sleep(3)

            filled_count = 0

            for field_name, value in template_data.items():
                # Type the value
                pyautogui.write(str(value), interval=0.05)
                time.sleep(delay)

                # Tab to next field
                pyautogui.press('tab')
                time.sleep(delay)

                filled_count += 1

            return {
                "success": True,
                "filled_fields": filled_count,
                "template_used": template_name,
                "method": "desktop_tab_navigation"
            }

        except Exception as e:
            return {"success": False, "error": str(e)}

    def fill_form_clipboard(self, template_name: str) -> Dict:
        """Fill form by copying values to clipboard for manual paste"""
        if not self.pyperclip_available:
            return {
                "success": False,
                "error": "Pyperclip not available",
                "help": self.get_missing_dependencies_message(['pyperclip'])
            }

        if template_name not in self.templates:
            return {"success": False, "error": f"Template '{template_name}' not found"}

        template_data = self.templates[template_name]

        try:
            print("Clipboard Form Filler Active!")
            print("Values will be copied to clipboard. Press Enter to copy next value.")
            print("Press 'q' and Enter to quit.\n")

            for field_name, value in template_data.items():
                print(f"\n{field_name}: {value}")
                user_input = input("Press Enter to copy (or 'q' to quit): ")

                if user_input.lower() == 'q':
                    break

                pyperclip.copy(str(value))
                print("✓ Copied to clipboard! You can now paste it.")

            return {
                "success": True,
                "template_used": template_name,
                "method": "clipboard"
            }

        except Exception as e:
            return {"success": False, "error": str(e)}

    def batch_fill_from_csv(self, csv_file: str, url: str, submit: bool = False) -> List[Dict]:
        """Fill multiple forms from CSV data"""
        if not self.pandas_available:
            return [{
                "success": False,
                "error": "Pandas not available",
                "help": self.get_missing_dependencies_message(['pandas'])
            }]

        if not self.selenium_available:
            return [{
                "success": False,
                "error": "Selenium not available",
                "help": self.get_missing_dependencies_message(['selenium'])
            }]

        results = []

        try:
            df = pd.read_csv(csv_file)

            for idx, row in df.iterrows():
                # Create temporary template
                row_num = int(idx) if isinstance(idx, (int, float)) else 0
                temp_template = f"batch_temp_{row_num}"
                self.templates[temp_template] = row.to_dict()

                # Fill form
                result = self.fill_web_form_selenium(url, temp_template, submit)
                result['row_number'] = row_num + 1
                results.append(result)

                # Clean up
                del self.templates[temp_template]

                # Delay between forms
                time.sleep(2)

            return results

        except Exception as e:
            return [{"success": False, "error": str(e)}]

    def batch_fill_from_excel(self, excel_file: str, url: str, sheet_name: Any = 0, submit: bool = False) -> List[Dict]:
        """Fill multiple forms from Excel data"""
        if not self.pandas_available:
            return [{
                "success": False,
                "error": "Pandas not available",
                "help": self.get_missing_dependencies_message(['pandas'])
            }]

        if not self.selenium_available:
            return [{
                "success": False,
                "error": "Selenium not available",
                "help": self.get_missing_dependencies_message(['selenium'])
            }]

        results = []

        try:
            df = pd.read_excel(excel_file, sheet_name=sheet_name)

            for idx, row in df.iterrows():
                # Create temporary template
                row_num = int(idx) if isinstance(idx, (int, float)) else 0
                temp_template = f"batch_temp_{row_num}"
                self.templates[temp_template] = row.to_dict()

                # Fill form
                result = self.fill_web_form_selenium(url, temp_template, submit)
                result['row_number'] = row_num + 1
                results.append(result)

                # Clean up
                del self.templates[temp_template]

                # Delay between forms
                time.sleep(2)

            return results

        except Exception as e:
            return [{"success": False, "error": str(e)}]

    def create_custom_template(self, template_name: str, data: Dict) -> Dict:
        """Create a new custom template"""
        self.templates[template_name] = data
        self.save_templates()

        return {
            "success": True,
            "message": f"Template '{template_name}' created successfully",
            "fields": len(data)
        }

    def update_template(self, template_name: str, updates: Dict) -> Dict:
        """Update an existing template"""
        if template_name not in self.templates:
            return {"success": False, "error": f"Template '{template_name}' not found"}

        self.templates[template_name].update(updates)
        self.save_templates()

        return {
            "success": True,
            "message": f"Template '{template_name}' updated successfully"
        }

    def delete_template(self, template_name: str) -> Dict:
        """Delete a template"""
        if template_name not in self.templates:
            return {"success": False, "error": f"Template '{template_name}' not found"}

        del self.templates[template_name]
        self.save_templates()

        return {
            "success": True,
            "message": f"Template '{template_name}' deleted successfully"
        }

    def list_templates(self) -> List[str]:
        """List all available templates"""
        return list(self.templates.keys())

    def get_template(self, template_name: str) -> Optional[Dict]:
        """Get a specific template"""
        return self.templates.get(template_name)

    def export_template_to_csv(self, template_name: str, output_file: str) -> Dict:
        """Export template to CSV for batch editing"""
        if not self.pandas_available:
            return {
                "success": False,
                "error": "Pandas not available",
                "help": self.get_missing_dependencies_message(['pandas'])
            }

        if template_name not in self.templates:
            return {"success": False, "error": f"Template '{template_name}' not found"}

        try:
            df = pd.DataFrame([self.templates[template_name]])
            df.to_csv(output_file, index=False)

            return {
                "success": True,
                "message": f"Template exported to {output_file}",
                "file": output_file
            }
        except Exception as e:
            return {"success": False, "error": str(e)}

    def get_fill_history(self) -> List[Dict]:
        """Get history of filled forms"""
        return self.fill_history

    def close_browser(self):
        """Close Selenium browser"""
        if self.driver:
            self.driver.quit()
            self.driver = None


# CLI interface for testing
if __name__ == "__main__":
    filler = BatchFormFiller()

    print("=" * 60)
    print("BATCH FORM FILLER")
    print("=" * 60)
    print(f"\nAvailable templates: {len(filler.list_templates())}")
    for template in filler.list_templates():
        print(f"  - {template}")

    print("\nExample usage:")
    print("1. Fill web form: filler.fill_web_form_selenium(url, 'job_application')")
    print("2. Fill desktop form: filler.fill_desktop_form_pyautogui('contact_form')")
    print("3. Clipboard mode: filler.fill_form_clipboard('registration_form')")
    print("4. Batch from CSV: filler.batch_fill_from_csv('data.csv', url)")

modules/automation/gesture_action_dispat.content:
"""
Gesture Action Dispatcher
Routes detected gestures to their configured actions
"""

import json
import time
import os
from typing import Dict, Optional, Callable
from modules.automation.window_control_helper import WindowControlHelper
from modules.automation.media_control_helper import MediaControlHelper


class GestureActionDispatcher:
    """
    Dispatches detected gestures to their configured actions.
    Handles cooldowns, priorities, and voice feedback.
    """

    def __init__(self, system_controller=None, voice_commander=None):
        self.system_controller = system_controller
        self.voice_commander = voice_commander

        # Helper modules
        self.window_control = WindowControlHelper()
        self.media_control = MediaControlHelper()

        # Load configuration
        self.config_path = "config/gesture_actions.json"
        self.config = self._load_config()

        # Cooldown tracking
        self.last_gesture_times = {}

        # Action callbacks
        self.custom_callbacks = {}

        # Statistics
        self.stats = {
            'total_gestures': 0,
            'gestures_by_type': {},
            'actions_executed': 0,
            'cooldown_blocked': 0
        }

    def _load_config(self) -> Dict:
        """Load gesture configuration from JSON file"""
        try:
            if os.path.exists(self.config_path):
                with open(self.config_path, 'r') as f:
                    return json.load(f)
            else:
                print(f"⚠️  Config file not found: {self.config_path}")
                return {"gestures": {}, "actions": {}, "settings": {}}
        except Exception as e:
            print(f"❌ Error loading config: {e}")
            return {"gestures": {}, "actions": {}, "settings": {}}

    def register_custom_callback(self, action_name: str, callback: Callable):
        """Register a custom callback for an action"""
        self.custom_callbacks[action_name] = callback

    def dispatch(self, gesture_id: str, confidence: float = 1.0, metadata: Optional[Dict] = None) -> Dict:
        """
        Dispatch a detected gesture to its configured action.

        Args:
            gesture_id: The gesture identifier (e.g., "OPEN_PALM", "THUMBS_UP")
            confidence: Detection confidence (0.0-1.0)
            metadata: Optional additional data about the gesture

        Returns:
            dict with 'success', 'message', and optional action result
        """
        self.stats['total_gestures'] += 1
        self.stats['gestures_by_type'][gesture_id] = self.stats['gestures_by_type'].get(gesture_id, 0) + 1

        # Get gesture configuration
        gesture_config = self.config.get('gestures', {}).get(gesture_id)

        if not gesture_config:
            return {
                'success': False,
                'message': f"Unknown gesture: {gesture_id}",
                'blocked': False
            }

        # Check if gesture is enabled
        if not gesture_config.get('enabled', True):
            return {
                'success': False,
                'message': f"Gesture {gesture_id} is disabled",
                'blocked': True
            }

        # Check confidence threshold
        settings = self.config.get('settings', {})
        min_confidence = settings.get('confidence_threshold', 0.7)
        if confidence < min_confidence:
            return {
                'success': False,
                'message': f"Low confidence: {confidence:.2f} < {min_confidence:.2f}",
                'blocked': True
            }

        # Check cooldown
        cooldown = gesture_config.get('cooldown', 1.0)
        current_time = time.time()
        last_time = self.last_gesture_times.get(gesture_id, 0)

        if current_time - last_time < cooldown:
            self.stats['cooldown_blocked'] += 1
            return {
                'success': False,
                'message': f"Cooldown active ({current_time - last_time:.1f}s/{cooldown}s)",
                'blocked': True
            }

        # Update last gesture time
        self.last_gesture_times[gesture_id] = current_time

        # Get action name
        action_name = gesture_config.get('action')
        if not action_name:
            return {
                'success': False,
                'message': f"No action configured for {gesture_id}"
            }

        # Execute action
        result = self._execute_action(action_name, gesture_id, gesture_config)

        if result.get('success'):
            self.stats['actions_executed'] += 1

            # Voice feedback if enabled
            if settings.get('enable_voice_feedback', True) and self.voice_commander:
                feedback = gesture_config.get('voice_feedback')
                if feedback:
                    self.voice_commander.speak(feedback)

        return result

    def _execute_action(self, action_name: str, gesture_id: str, gesture_config: Dict) -> Dict:
        """Execute the specified action"""

        # Check for custom callback first
        if action_name in self.custom_callbacks:
            try:
                return self.custom_callbacks[action_name](gesture_id, gesture_config)
            except Exception as e:
                return {'success': False, 'message': f"Callback error: {e}"}

        # Get action configuration
        action_config = self.config.get('actions', {}).get(action_name, {})
        module = action_config.get('module')
        method = action_config.get('method')
        params = action_config.get('params', {})

        if not module or not method:
            return {'success': False, 'message': f"Invalid action config: {action_name}"}

        # Route to appropriate module
        try:
            if module == 'system_control' and self.system_controller:
                return self._execute_system_action(method, params)
            elif module == 'window_control':
                return self._execute_window_action(method, params)
            elif module == 'media_control':
                return self._execute_media_action(method, params)
            elif module == 'voice_commander' and self.voice_commander:
                return self._execute_voice_action(method, params)
            elif module == 'gesture_detector':
                # Special internal actions
                return self._execute_internal_action(method, gesture_id)
            else:
                return {'success': False, 'message': f"Unknown module: {module}"}
        except Exception as e:
            return {'success': False, 'message': f"Action execution error: {e}"}

    def _execute_system_action(self, method: str, params: Dict) -> Dict:
        """Execute system control action"""
        if not self.system_controller:
            return {'success': False, 'message': "System controller not available"}

        try:
            if method == 'lock_screen':
                result = self.system_controller.lock_screen()
            elif method == 'increase_volume':
                amount = params.get('amount', 10)
                result = self.system_controller.increase_volume(amount)
            elif method == 'decrease_volume':
                amount = params.get('amount', 10)
                result = self.system_controller.decrease_volume(amount)
            elif method == 'take_screenshot':
                import pyautogui
                filename = f"screenshot_{int(time.time())}.png"
                pyautogui.screenshot(filename)
                result = f"Screenshot saved: {filename}"
            elif method == 'toggle_screen_recording':
                result = "Screen recording toggle not yet implemented"
            else:
                result = f"Unknown system method: {method}"

            return {'success': True, 'message': result}
        except Exception as e:
            return {'success': False, 'message': f"System action error: {e}"}

    def _execute_window_action(self, method: str, params: Dict) -> Dict:
        """Execute window control action"""
        try:
            if method == 'minimize_active_window':
                return self.window_control.minimize_active_window()
            elif method == 'maximize_active_window':
                return self.window_control.maximize_active_window()
            elif method == 'close_active_window':
                return self.window_control.close_active_window()
            elif method == 'switch_desktop':
                direction = params.get('direction', 'right')
                return self.window_control.switch_desktop(direction)
            elif method == 'show_desktop':
                return self.window_control.show_desktop()
            else:
                return {'success': False, 'message': f"Unknown window method: {method}"}
        except Exception as e:
            return {'success': False, 'message': f"Window action error: {e}"}

    def _execute_media_action(self, method: str, params: Dict) -> Dict:
        """Execute media control action"""
        try:
            if method == 'play_pause':
                return self.media_control.play_pause()
            elif method == 'next_track':
                return self.media_control.next_track()
            elif method == 'previous_track':
                return self.media_control.previous_track()
            elif method == 'stop':
                return self.media_control.stop()
            else:
                return {'success': False, 'message': f"Unknown media method: {method}"}
        except Exception as e:
            return {'success': False, 'message': f"Media action error: {e}"}

    def _execute_voice_action(self, method: str, params: Dict) -> Dict:
        """Execute voice commander action"""
        if not self.voice_commander:
            return {'success': False, 'message': "Voice commander not available"}

        try:
            # Dynamically call the voice commander method
            if hasattr(self.voice_commander, method):
                method_func = getattr(self.voice_commander, method)
                result = method_func(**params) if params else method_func()

                # Handle different return types
                if isinstance(result, dict):
                    return result
                else:
                    return {'success': True, 'message': f"Voice action executed: {method}"}
            else:
                return {'success': False, 'message': f"Unknown voice method: {method}"}
        except Exception as e:
            return {'success': False, 'message': f"Voice action error: {e}"}

    def _execute_internal_action(self, method: str, gesture_id: str) -> Dict:
        """Execute internal gesture detector actions"""
        # These are handled by the detector itself via callbacks
        return {'success': True, 'message': f"Internal action: {method}"}

    def get_stats(self) -> Dict:
        """Get dispatcher statistics"""
        return self.stats.copy()

    def reset_stats(self):
        """Reset statistics"""
        self.stats = {
            'total_gestures': 0,
            'gestures_by_type': {},
            'actions_executed': 0,
            'cooldown_blocked': 0
        }

    def get_gesture_list(self) -> list:
        """Get list of all configured gestures"""
        gestures = []
        for gesture_id, config in self.config.get('gestures', {}).items():
            gestures.append({
                'id': gesture_id,
                'action': config.get('action'),
                'description': config.get('description'),
                'enabled': config.get('enabled', True),
                'cooldown': config.get('cooldown', 1.0)
            })
        return gestures

modules/automation/window_control_helper.content:
"""
Window Control Helper for Gesture Actions
Provides cross-platform window management functionality
"""

import platform
import subprocess
import pyautogui


class WindowControlHelper:
    """Helper class for window management operations"""

    def __init__(self):
        self.os = platform.system()

    def minimize_active_window(self):
        """Minimize the currently active window"""
        try:
            if self.os == "Windows":
                pyautogui.hotkey('win', 'down')
                return {"success": True, "message": "Window minimized"}
            elif self.os == "Darwin":
                pyautogui.hotkey('command', 'm')
                return {"success": True, "message": "Window minimized"}
            elif self.os == "Linux":
                pyautogui.hotkey('super', 'h')
                return {"success": True, "message": "Window minimized"}
        except Exception as e:
            return {"success": False, "message": f"Failed to minimize: {e}"}

    def maximize_active_window(self):
        """Maximize the currently active window"""
        try:
            if self.os == "Windows":
                pyautogui.hotkey('win', 'up')
                return {"success": True, "message": "Window maximized"}
            elif self.os == "Darwin":
                # macOS doesn't have a standard maximize hotkey
                # Use green button simulation
                pyautogui.hotkey('ctrl', 'command', 'f')
                return {"success": True, "message": "Window fullscreen"}
            elif self.os == "Linux":
                pyautogui.hotkey('super', 'up')
                return {"success": True, "message": "Window maximized"}
        except Exception as e:
            return {"success": False, "message": f"Failed to maximize: {e}"}

    def close_active_window(self):
        """Close the currently active window"""
        try:
            if self.os == "Windows":
                pyautogui.hotkey('alt', 'f4')
                return {"success": True, "message": "Window closed"}
            elif self.os == "Darwin":
                pyautogui.hotkey('command', 'w')
                return {"success": True, "message": "Window closed"}
            elif self.os == "Linux":
                pyautogui.hotkey('alt', 'f4')
                return {"success": True, "message": "Window closed"}
        except Exception as e:
            return {"success": False, "message": f"Failed to close window: {e}"}

    def switch_desktop(self, direction="right"):
        """Switch to next/previous virtual desktop"""
        try:
            if self.os == "Windows":
                if direction == "right":
                    pyautogui.hotkey('ctrl', 'win', 'right')
                else:
                    pyautogui.hotkey('ctrl', 'win', 'left')
                return {"success": True, "message": f"Switched desktop {direction}"}
            elif self.os == "Darwin":
                if direction == "right":
                    pyautogui.hotkey('ctrl', 'right')
                else:
                    pyautogui.hotkey('ctrl', 'left')
                return {"success": True, "message": f"Switched desktop {direction}"}
            elif self.os == "Linux":
                if direction == "right":
                    pyautogui.hotkey('ctrl', 'alt', 'right')
                else:
                    pyautogui.hotkey('ctrl', 'alt', 'left')
                return {"success": True, "message": f"Switched desktop {direction}"}
        except Exception as e:
            return {"success": False, "message": f"Failed to switch desktop: {e}"}

    def show_desktop(self):
        """Show desktop / minimize all windows"""
        try:
            if self.os == "Windows":
                pyautogui.hotkey('win', 'd')
            elif self.os == "Darwin":
                pyautogui.hotkey('f11')
            elif self.os == "Linux":
                pyautogui.hotkey('ctrl', 'alt', 'd')
            return {"success": True, "message": "Desktop shown"}
        except Exception as e:
            return {"success": False, "message": f"Failed to show desktop: {e}"}

modules/automation/media_control_helper..content:
"""
Media Control Helper for Gesture Actions
Provides cross-platform media playback control
"""

import platform
import pyautogui


class MediaControlHelper:
    """Helper class for media control operations"""

    def __init__(self):
        self.os = platform.system()

    def play_pause(self):
        """Toggle play/pause for media"""
        try:
            pyautogui.press('playpause')
            return {"success": True, "message": "Play/Pause toggled"}
        except Exception as e:
            return {"success": False, "message": f"Failed to toggle play/pause: {e}"}

    def next_track(self):
        """Skip to next track"""
        try:
            pyautogui.press('nexttrack')
            return {"success": True, "message": "Next track"}
        except Exception as e:
            return {"success": False, "message": f"Failed to skip track: {e}"}

    def previous_track(self):
        """Go to previous track"""
        try:
            pyautogui.press('prevtrack')
            return {"success": True, "message": "Previous track"}
        except Exception as e:
            return {"success": False, "message": f"Failed to go to previous track: {e}"}

    def stop(self):
        """Stop media playback"""
        try:
            pyautogui.press('stop')
            return {"success": True, "message": "Media stopped"}
        except Exception as e:
            return {"success": False, "message": f"Failed to stop: {e}"}

    def volume_up(self, steps=1):
        """Increase volume"""
        try:
            for _ in range(steps):
                pyautogui.press('volumeup')
            return {"success": True, "message": f"Volume increased"}
        except Exception as e:
            return {"success": False, "message": f"Failed to increase volume: {e}"}

    def volume_down(self, steps=1):
        """Decrease volume"""
        try:
            for _ in range(steps):
                pyautogui.press('volumedown')
            return {"success": True, "message": f"Volume decreased"}
        except Exception as e:
            return {"success": False, "message": f"Failed to decrease volume: {e}"}

    def mute(self):
        """Mute/unmute volume"""
        try:
            pyautogui.press('volumemute')
            return {"success": True, "message": "Volume muted/unmuted"}
        except Exception as e:
            return {"success": False, "message": f"Failed to mute: {e}"}

